--

CREATE FUNCTION alissonerp.fn_audit_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO alissonerp.audit_log (tabela, operacao, registro_id, dados_antes, dados_depois, usuario_id)
  VALUES (
    TG_TABLE_NAME, TG_OP,
    COALESCE(NEW.id::text, OLD.id::text),
    CASE WHEN TG_OP IN ('UPDATE','DELETE') THEN to_jsonb(OLD) END,
    CASE WHEN TG_OP IN ('INSERT','UPDATE') THEN to_jsonb(NEW) END,
    COALESCE(current_setting('request.jwt.claims', true)::jsonb->>'sub', NULL)::uuid
  );
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: fn_auditar_divergencia_total(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_auditar_divergencia_total() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_pub_total NUMERIC;
BEGIN
  IF NEW.public_venda_id IS NULL THEN RETURN NEW; END IF;

  SELECT total_venda INTO v_pub_total
  FROM public.vendas WHERE id = NEW.public_venda_id;

  IF v_pub_total IS NOT NULL
     AND ABS(NEW.total_venda - v_pub_total) > GREATEST(v_pub_total * 0.01, 10)
  THEN
    RAISE WARNING 'ALERTA DIVERGENCIA: venda % (ERP#%) total_venda=R$% public=R$% (diff=R$%)',
      NEW.numero_venda, NEW.id,
      NEW.total_venda, v_pub_total,
      NEW.total_venda - v_pub_total;
  END IF;

  RETURN NEW;
END;
$_$;


--
-- Name: fn_auto_auditoria_loja(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_auto_auditoria_loja() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
    DECLARE
      v_audit_id INTEGER;
    BEGIN
      -- Ignora ordens de teste ou sem rota definida que não precisam de auditoria
      IF NEW.eh_teste = TRUE THEN RETURN NEW; END IF;
      IF NEW.rota IS NULL THEN RETURN NEW; END IF;

      -- Só cria se ainda não existe auditoria loja ativa para esta ordem
      IF EXISTS (
        SELECT 1 FROM alissonerp.auditorias
        WHERE ordem_id = NEW.id AND tipo_auditoria = 'loja' AND situacao != 'reprovado'
      ) THEN
        RETURN NEW;
      END IF;

      INSERT INTO alissonerp.auditorias (
        situacao, tipo_auditoria, rota_processo, ordem_id,
        peso_negociado, parecer, dados_ordem
      ) VALUES (
        'pendente', 'loja', 'entrada_ordem', NEW.id,
        COALESCE(NEW.peso_metal_negociado, 0), NULL,
        jsonb_build_object(
          'numero_ordem', NEW.numero_ordem,
          'tipo_ordem',   NEW.tipo_ordem::text,
          'rota',         NEW.rota::text,
          'origem',       'trigger_auto'
        )
      ) RETURNING id INTO v_audit_id;

      -- Aprovação imediata dispara fn_processar_auditoria (BEFORE UPDATE)
      UPDATE alissonerp.auditorias
      SET situacao = 'aprovado', data_conclusao = NOW(),
          parecer  = 'Aprovação automática — trigger'
      WHERE id = v_audit_id;

      RETURN NEW;
    END;
    $$;


--
-- Name: fn_bloquear_compra(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_bloquear_compra() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.bloqueado = true AND NEW.situacao != OLD.situacao THEN
    RAISE EXCEPTION 'Compra #% está bloqueada para edição', OLD.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_bloquear_compra_comercial(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_bloquear_compra_comercial() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.bloqueado = true AND NEW.situacao IS DISTINCT FROM OLD.situacao THEN
    IF NEW.situacao IN ('aprovado', 'rejeitado') THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'Compra comercial #% está bloqueada para edição', OLD.id;
  END IF;
  RETURN NEW;
END;
$$;


