--
-- Name: fn_calc_qty_after_sle(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_calc_qty_after_sle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_prev_qty NUMERIC(16,4);
BEGIN
  SELECT qty_after INTO v_prev_qty
  FROM alissonerp.stock_ledger_entry
  WHERE item_id = NEW.item_id
    AND item_type = NEW.item_type
    AND warehouse_id = NEW.warehouse_id
    AND is_cancelled = false
    AND id != NEW.id
  ORDER BY posting_date DESC, posting_time DESC, id DESC
  LIMIT 1;
  NEW.qty_after := COALESCE(v_prev_qty, 0) + NEW.actual_qty;
  RETURN NEW;
END;
$$;


--
-- Name: fn_calcular_item_compra(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_calcular_item_compra() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cat INTEGER;
BEGIN
  SELECT categoria_id INTO v_cat
  FROM alissonerp.insumos WHERE id = NEW.insumo_id;

  IF v_cat = 2
     AND NEW.peso_ct IS NOT NULL AND NEW.peso_ct > 0
     AND NEW.custo_por_ct IS NOT NULL AND NEW.custo_por_ct > 0 THEN
    -- Pedras: pre??o total em ct
    NEW.valor_total := ROUND((NEW.peso_ct * NEW.custo_por_ct)::numeric, 2);
  ELSE
    -- Padr??o: qtd ?? valor_unit??rio
    NEW.valor_total := ROUND(
      (COALESCE(NEW.qtd, 0) * COALESCE(NEW.valor_unitario, 0))::numeric,
      2
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_calcular_item_compra_comercial(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_calcular_item_compra_comercial() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.valor_total := ROUND((COALESCE(NEW.peso_total, 0) * COALESCE(NEW.valor_grama, 0))::numeric, 2);
  RETURN NEW;
END;
$$;


--
-- Name: fn_calcular_peso_pedra_gramas(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_calcular_peso_pedra_gramas() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.peso_pedra_ct IS NOT NULL AND (
    OLD.peso_pedra_ct IS NULL OR 
    NEW.peso_pedra_ct IS DISTINCT FROM OLD.peso_pedra_ct
  ) THEN
    NEW.peso_pedra = NEW.peso_pedra_ct * 0.2;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_calcular_pmc_distribuicao(real, real, real, real); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_calcular_pmc_distribuicao(p_peso_final real, p_total_outros real, p_entrada real, p_retorno real) RETURNS TABLE(pmc real, quebra real, percentual real)
    LANGUAGE plpgsql
    AS $$
DECLARE v_pmc REAL; v_quebra REAL; v_pct REAL;
BEGIN
  v_pmc:=p_peso_final-p_total_outros; v_quebra:=p_entrada-v_pmc;
  v_pct:=CASE WHEN v_pmc!=0 THEN (v_quebra/v_pmc*100) ELSE 0 END;
  RETURN QUERY SELECT ROUND(v_pmc::numeric,3)::REAL,ROUND(v_quebra::numeric,3)::REAL,ROUND(v_pct::numeric,2)::REAL;
END;
$$;


--
-- Name: fn_calcular_pmc_pcp(real, real, real, real, real); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_calcular_pmc_pcp(p_peso_final real, p_total_outros real, p_metal_externo real, p_entrada real, p_retorno real) RETURNS TABLE(pmc real, quebra real, percentual real)
    LANGUAGE plpgsql
    AS $$
DECLARE v_pmc REAL; v_consumo REAL; v_quebra REAL; v_pct REAL;
BEGIN
  IF p_entrada = 0 THEN RETURN QUERY SELECT 0::REAL,0::REAL,0::REAL; RETURN; END IF;
  v_pmc:=p_peso_final-p_total_outros-p_metal_externo; v_consumo:=p_entrada-p_retorno;
  v_quebra:=v_consumo-v_pmc;
  v_pct:=CASE WHEN v_consumo!=0 THEN (v_quebra/v_consumo*100) ELSE 0 END;
  RETURN QUERY SELECT ROUND(v_pmc::numeric,2)::REAL,ROUND(v_quebra::numeric,2)::REAL,ROUND(v_pct::numeric,2)::REAL;
END;
$$;


--
-- Name: fn_cancelar_pcp_ordem(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_cancelar_pcp_ordem() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
          IF NEW.situacao::text = 'cancelado' AND OLD.situacao::text != 'cancelado' THEN
            UPDATE alissonerp.pcp
            SET etapas = 'cancelado', bloqueado = true
            WHERE ordem_id = NEW.id
              AND etapas::text != 'cancelado';
          END IF;
          RETURN NEW;
        END;
        $$;


