--
-- Name: fn_concluir_compra(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_concluir_compra() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_item     RECORD;
  v_entrada  REAL;
  v_local_id INTEGER;
BEGIN
  IF NEW.situacao != 'concluido' THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.situacao = 'concluido' THEN RETURN NEW; END IF;

  -- Guard: transi????o de status v??lida
  IF TG_OP = 'UPDATE' AND OLD.situacao NOT IN ('rascunho', 'recebida') THEN
    RAISE EXCEPTION 'Compra #% precisa estar em rascunho ou recebida para concluir (status atual: %)',
      OLD.id, OLD.situacao;
  END IF;

  -- Local de destino: usa local_destino_id se preenchido, sen??o F??brica (1)
  v_local_id := COALESCE(NEW.local_destino_id, 1);

  FOR v_item IN
    SELECT ic.*, i.categoria_id
    FROM alissonerp.itens_compra ic
    JOIN alissonerp.insumos i ON i.id = ic.insumo_id
    WHERE ic.compra_id = NEW.id
  LOOP
    -- Pedras: CE em ct | Outros: CE em qtd (gramas/ml/un)
    IF v_item.categoria_id = 2
       AND v_item.peso_ct IS NOT NULL
       AND v_item.peso_ct > 0 THEN
      v_entrada := v_item.peso_ct;
    ELSE
      v_entrada := v_item.qtd;
    END IF;

    INSERT INTO alissonerp.movimentacoes_estoque
      (entrada, saida, insumo_id, deposito_id,
       marcador, obs, preco_compra, valor_total, local_estoque_id)
    VALUES
      (v_entrada, 0, v_item.insumo_id,
       COALESCE(v_item.deposito_id, 1),
       'EA'::alissonerp.enum_marcador_estoque,
       'Entrada via compra #' || NEW.id,
       v_item.valor_unitario, v_item.valor_total,
       v_local_id);
  END LOOP;

  NEW.bloqueado := true;

  SELECT COALESCE(SUM(valor_total), 0) INTO NEW.total
  FROM alissonerp.itens_compra WHERE compra_id = NEW.id;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_concluir_compra(); Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON FUNCTION alissonerp.fn_concluir_compra() IS 'Concluir compra → CE entrada por item + bloquear edição.';


--
-- Name: fn_concluir_compra_comercial(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_concluir_compra_comercial() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_item RECORD;
BEGIN
  IF NEW.situacao != 'concluido' THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.situacao = 'concluido' THEN RETURN NEW; END IF;

  IF TG_OP = 'UPDATE' AND OLD.situacao NOT IN ('rascunho', 'recebida') THEN
    RAISE EXCEPTION 'Compra comercial #% precisa estar em rascunho ou recebida para concluir (status atual: %)',
      OLD.id, OLD.situacao;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM alissonerp.itens_compra_comercial ic
    WHERE ic.compra_comercial_id = NEW.id
  ) THEN
    RAISE EXCEPTION 'Compra comercial #% não possui itens para concluir', NEW.id;
  END IF;

  FOR v_item IN
    SELECT ic.*
    FROM alissonerp.itens_compra_comercial ic
    WHERE ic.compra_comercial_id = NEW.id
  LOOP
    INSERT INTO alissonerp.movimentacoes_estoque_comercial
      (produto_id, tipo, quantidade, motivo, local_estoque_id, status, observacao, created_by)
    VALUES
      (v_item.produto_id, 'entrada', v_item.qtd, 'compra_comercial', NEW.local_estoque_id, 'efetivado',
       'Entrada via compra comercial #' || NEW.id,
       COALESCE(NEW.created_by, auth.uid()));
  END LOOP;

  NEW.bloqueado := true;

  SELECT COALESCE(SUM(valor_total), 0) INTO NEW.total
  FROM alissonerp.itens_compra_comercial
  WHERE compra_comercial_id = NEW.id;

  RETURN NEW;
END;
$$;


--
-- Name: fn_concluir_distribuicao(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_concluir_distribuicao() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_pmc           REAL;
  v_quebra        REAL;
  v_pct           REAL;
  v_metal_liquido REAL;
BEGIN
  IF NEW.etapas != 'concluido' THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.etapas = 'concluido' THEN RETURN NEW; END IF;

  v_pmc    := COALESCE(NEW.peso_final, 0) - COALESCE(NEW.total_geral_outros_pesos, 0);
  v_quebra := (COALESCE(NEW.total_metal, 0) - COALESCE(NEW.retorno_metal, 0)) - v_pmc;

  -- metal_liquido: usa ouro_entregue (novo sistema) ou total_metal-retorno (legado)
  v_metal_liquido := COALESCE(
    NULLIF(NEW.ouro_entregue, 0),
    COALESCE(NEW.total_metal, 0) - COALESCE(NEW.retorno_metal, 0)
  );

  v_pct := CASE WHEN v_metal_liquido > 0
    THEN ROUND((v_quebra / v_metal_liquido * 100)::numeric, 2)::REAL
    ELSE 0
  END;

  -- CE TEDMD e TEDPD removidos — conclusão do lote é só administrativa.
  -- ZERO INSERT em movimentacoes_estoque (saída por ordem cobre o estoque).

  NEW.pmc                   := ROUND(v_pmc::numeric, 3);
  NEW.quebra                := ROUND(v_quebra::numeric, 3);
  NEW.porcentagem_de_quebra := v_pct;
  NEW.updated_at            := now();

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_concluir_distribuicao(); Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON FUNCTION alissonerp.fn_concluir_distribuicao() IS 'Flow 1014: PMC=pf-outros (sem metal_ext), quebra=(entrada-retorno)-PMC, %=quebra/PMC. CE TEDMD+TEDPD.';


--
-- Name: fn_concluir_protocolo(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_concluir_protocolo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_rec      RECORD;
  v_saida_id INTEGER;
BEGIN
  -- Guard: so ao transicionar para 'concluido'
  IF NEW.etapas != 'concluido' THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.etapas = 'concluido' THEN RETURN NEW; END IF;

  IF NEW.direcao = 'ida' THEN
    -- Flow 03: para cada ordem → saida_ordem vazia + PCP + atualiza ordem
    FOR v_rec IN
      SELECT o.id            AS ordem_id,
             COALESCE(o.peso_metal_externo, 0) AS metal_ext
      FROM alissonerp.protocolo_ordens po
      JOIN alissonerp.ordens o ON po.ordem_id = o.id
      WHERE po.protocolo_id = NEW.id
    LOOP
      -- Saida vazia (trigger em saidas_ordem e no-op pois peso=NULL com o novo guard)
      INSERT INTO alissonerp.saidas_ordem (ordem_id)
      VALUES (v_rec.ordem_id) RETURNING id INTO v_saida_id;

      -- PCP com zeros explicitos para evitar NULL + aritmetica
      INSERT INTO alissonerp.pcp (
        ordem_id, etapas, saida_ordem_id, metal_externo,
        total_metal, retorno_metal, total_pedras_un, total_pedras_g,
        total_geral_outros_pesos, total_outros_pesos_g
      ) VALUES (
        v_rec.ordem_id, 'novas_ordens', v_saida_id, v_rec.metal_ext,
        0, 0, 0, 0, 0, 0
      );

      -- Ordem → em_andamento
      UPDATE alissonerp.ordens
      SET status = 'em_andamento', updated_at = now()
      WHERE id = v_rec.ordem_id;
    END LOOP;

  ELSIF NEW.direcao = 'volta' THEN
    -- Flow 05: para cada ordem → aprovacao_consultora pendente
    FOR v_rec IN
      SELECT o.id AS ordem_id, o.vendedor_id
      FROM alissonerp.protocolo_ordens po
      JOIN alissonerp.ordens o ON po.ordem_id = o.id
      WHERE po.protocolo_id = NEW.id
    LOOP
      INSERT INTO alissonerp.aprovacoes_consultora (etapas, ordem_id, consultora_id)
      VALUES ('pendente', v_rec.ordem_id, v_rec.vendedor_id);
    END LOOP;
  END IF;

  -- Marcar data de conclusao
  NEW.data_conclusao := now();
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_concluir_protocolo(); Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON FUNCTION alissonerp.fn_concluir_protocolo() IS 'Flows 03+05: ida→cria PCPs em batch (saida_ordem vazia + pcp com zeros). volta→cria aprovacoes_consultora.';


--
-- Name: fn_concluir_protocolo_conversao(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_concluir_protocolo_conversao() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_conversao     RECORD;
  v_ordem         RECORD;
  v_item          RECORD;
  v_mov_baixa     BIGINT;
  v_insumo_id     INTEGER;
  v_local_loja    INTEGER := 2;
  v_local_fabrica INTEGER := 1;
BEGIN
  IF NEW.etapas::text != 'concluido' THEN
    RETURN NEW;
  END IF;

  FOR v_ordem IN
    SELECT o.id, o.numero_ordem
    FROM alissonerp.protocolo_ordens po
    JOIN alissonerp.ordens o ON o.id = po.ordem_id
    WHERE po.protocolo_id = NEW.id
      AND o.tipo_ordem::text = 'conversao'
  LOOP
    SELECT * INTO v_conversao
    FROM alissonerp.conversoes_estoque
    WHERE ordem_id = v_ordem.id
    LIMIT 1;

    IF NOT FOUND THEN CONTINUE; END IF;

    -- GUARD Conversão 2.0: se já entrou no Caixa de Ouro, pular
    -- A baixa do estoque comercial já foi feita no momento da aprovação
    IF v_conversao.cofre_registrado = true THEN
      CONTINUE;
    END IF;

    UPDATE alissonerp.conversoes_estoque
    SET status_conversao = 'concluido'
    WHERE id = v_conversao.id;

    FOR v_item IN
      SELECT * FROM alissonerp.conversao_itens
      WHERE conversao_id = v_conversao.id
    LOOP
      IF v_item.reserva_id IS NOT NULL THEN
        UPDATE alissonerp.reservas_estoque_comercial
        SET status = 'efetivado', efetivado_em = NOW()
        WHERE id = v_item.reserva_id;

        INSERT INTO alissonerp.movimentacoes_estoque_comercial
          (produto_id, tipo, quantidade, motivo, local_estoque_id, status, ordem_id, protocolo_id, referencia_id, observacao, created_by)
        VALUES
          (v_item.produto_id, 'saida', v_item.quantidade, 'virou_peso', v_local_loja, 'efetivado',
           v_conversao.ordem_id, NEW.id, v_conversao.ordem_id,
           'Conversao de estoque — virou peso (Ordem ' || v_ordem.numero_ordem || ')',
           NEW.recebedor_id)
        RETURNING id INTO v_mov_baixa;

        UPDATE alissonerp.conversao_itens
        SET movimento_baixa_id = v_mov_baixa
        WHERE id = v_item.id;

      ELSIF v_item.movimento_reserva_id IS NOT NULL THEN
        v_mov_baixa := v_item.movimento_reserva_id;

        UPDATE alissonerp.conversao_itens
        SET movimento_baixa_id = v_mov_baixa
        WHERE id = v_item.id;

      ELSE
        RAISE WARNING 'Conversao item % sem reserva_id nem movimento_reserva_id — pulando', v_item.id;
      END IF;
    END LOOP;

    v_insumo_id := COALESCE(v_conversao.insumo_destino, 1);

    INSERT INTO alissonerp.movimentacoes_estoque
      (entrada, insumo_id, deposito_id, local_estoque_id, marcador, ordem_id, obs)
    VALUES
      (v_conversao.peso_total, v_insumo_id, v_local_fabrica, v_local_fabrica,
       'EM'::alissonerp.enum_marcador_estoque, v_conversao.ordem_id,
       'Conversao de estoque — entrada de ' || v_conversao.peso_total || 'g de metal (Ordem ' || v_ordem.numero_ordem || ')');

    UPDATE alissonerp.ordens
    SET status = 'concluido', data_conclusao = NOW(), updated_at = NOW()
    WHERE id = v_ordem.id;
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: fn_concluir_protocolo_conversao_sku(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_concluir_protocolo_conversao_sku() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_ordem        RECORD;
  v_conv         RECORD;
  v_mov_id       BIGINT;
  v_local_id     INTEGER;
  v_origem_nome  TEXT;
  v_destino_nome TEXT;
  v_detalhes     TEXT;
BEGIN
  IF NEW.etapas::text != 'concluido' THEN RETURN NEW; END IF;
  IF NEW.tipo_protocolo = 'service' THEN v_local_id := 3; ELSE v_local_id := 1; END IF;


DECLARE
  v_ordem        RECORD;
  v_conv         RECORD;
  v_mov_id       BIGINT;
  v_local_id     INTEGER;
  v_origem_nome  TEXT;
  v_destino_nome TEXT;
  v_detalhes     TEXT;
BEGIN
  IF NEW.etapas::text != 'concluido' THEN RETURN NEW; END IF;
  IF NEW.tipo_protocolo = 'service' THEN v_local_id := 3; ELSE v_local_id := 1; END IF;

  FOR v_ordem IN
    SELECT o.id, o.numero_ordem
    FROM alissonerp.protocolo_ordens po
    JOIN alissonerp.ordens o ON o.id = po.ordem_id
    WHERE po.protocolo_id = NEW.id AND o.tipo_ordem::text = 'conversao_sku'
  LOOP
    SELECT * INTO v_conv FROM alissonerp.conversoes_sku WHERE ordem_id = v_ordem.id LIMIT 1;
    IF NOT FOUND THEN CONTINUE; END IF;

    IF NEW.direcao::text = 'ida' THEN
      INSERT INTO alissonerp.movimentacoes_estoque_comercial
        (produto_id, tipo, quantidade, motivo, local_estoque_id, status, ordem_id, protocolo_id, observacao, created_by)
      VALUES
        (v_conv.sku_origem_id, 'entrada', v_conv.sku_origem_quantidade,
         'conversao_sku_ida', v_local_id, 'efetivado', v_conv.ordem_id, NEW.id,
         'Entrada CS ' || COALESCE(v_ordem.numero_ordem, '#' || v_ordem.id),
         NEW.recebedor_id);

      UPDATE alissonerp.conversoes_sku SET status_conversao = 'em_fabrica', updated_at = NOW() WHERE id = v_conv.id;

      SELECT nome INTO v_origem_nome FROM public.produtos WHERE id_produto = v_conv.sku_origem_id;
      SELECT nome INTO v_destino_nome FROM public.produtos WHERE id_produto = v_conv.sku_destino_id;
      v_detalhes := 'CONVERSAO DE SKU' || chr(10) ||
                    'ORIGEM: ' || COALESCE(v_origem_nome, 'N/D') || chr(10) ||
                    '   Peso: ' || v_conv.sku_origem_peso || 'g' || chr(10) ||
                    '   Qtd: ' || v_conv.sku_origem_quantidade || chr(10) ||
                    'DESTINO: ' || COALESCE(v_destino_nome, 'N/D') || chr(10) ||
                    '   Qtd desejada: ' || v_conv.sku_destino_quantidade_desejada || chr(10) ||
    CASE WHEN v_conv.motivo IS NOT NULL THEN 'MOTIVO: ' || v_conv.motivo || chr(10) ELSE '' END ||
                    'Para concluir informe: peso final, qtd produzida, foto balanca, peso sobra e foto sobra.';

      UPDATE alissonerp.ordens SET detalhes_ordem = v_detalhes, updated_at = NOW() WHERE id = v_ordem.id;

    ELSIF NEW.direcao::text = 'volta' THEN
      INSERT INTO alissonerp.movimentacoes_estoque_comercial
        (produto_id, tipo, quantidade, motivo, local_estoque_id, status, ordem_id, protocolo_id, observacao, created_by)
      VALUES
        (v_conv.sku_destino_id, 'entrada', COALESCE(v_conv.quantidade_produzida, v_conv.sku_destino_quantidade_desejada),
         'conversao_sku_volta', v_conv.local_destino_id, 'efetivado', v_conv.ordem_id, NEW.id,
         'Entrada CS ' || COALESCE(v_ordem.numero_ordem, '#' || v_ordem.id),
         NEW.recebedor_id);

      UPDATE alissonerp.conversoes_sku SET status_conversao = 'concluido', updated_at = NOW() WHERE id = v_conv.id;
      UPDATE alissonerp.ordens SET status = 'concluido', data_conclusao = NOW(), updated_at = NOW() WHERE id = v_ordem.id;
    END IF;
  END LOOP;
  RETURN NEW;
END;


END;
$$;


--
-- Name: fn_cr_marcar_pago_mp(integer); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_cr_marcar_pago_mp(p_venda_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
    DECLARE
      v_count INTEGER;
    BEGIN
      UPDATE alissonerp.contas_receber
      SET
        situacao         = 'pago',
        data_recebimento = CURRENT_DATE,
        updated_at       = NOW()
      WHERE venda_erp_id = p_venda_id
        AND situacao     = 'pendente';

      GET DIAGNOSTICS v_count = ROW_COUNT;
      RETURN v_count;
    END;
    $$;


