--
-- Name: fn_criar_item_distribuicao(integer, integer, integer, real, integer); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_criar_item_distribuicao(p_dist_id integer, p_insumo_id integer, p_deposito_id integer, p_qtd real, p_tipo integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_existente INTEGER;
  v_mult REAL := CASE WHEN p_tipo IN (5, 6) THEN -1.0 ELSE 1.0 END;
BEGIN
  SELECT id INTO v_existente
  FROM alissonerp.itens_distribuicao
  WHERE distribuicao_id = p_dist_id AND insumo_id = p_insumo_id;

  IF v_existente IS NOT NULL THEN
    UPDATE alissonerp.itens_distribuicao
    SET peso = peso + (p_qtd * v_mult)
    WHERE id = v_existente;
  ELSE
    INSERT INTO alissonerp.itens_distribuicao (distribuicao_id, deposito_id, insumo_id, peso)
    VALUES (p_dist_id, p_deposito_id, p_insumo_id, p_qtd * v_mult);
  END IF;
END;
$$;


--
-- Name: FUNCTION fn_criar_item_distribuicao(p_dist_id integer, p_insumo_id integer, p_deposito_id integer, p_qtd real, p_tipo integer); Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON FUNCTION alissonerp.fn_criar_item_distribuicao(p_dist_id integer, p_insumo_id integer, p_deposito_id integer, p_qtd real, p_tipo integer) IS 'Flow 1011: Upsert em itens_distribuicao. Tipos 5,6 subtraem.';


--
-- Name: fn_criar_itens_ordem(integer, integer, integer, real, integer); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_criar_itens_ordem(p_ordem_id integer, p_insumo_id integer, p_deposito_id integer, p_qtd real, p_tipo_apontamento integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_item_existente INTEGER;
  v_multiplicador REAL;
BEGIN
  -- Retornos (tipo 5,6) subtraem; entradas (tipo 1,2,3,4) somam
  v_multiplicador := CASE WHEN p_tipo_apontamento IN (5, 6) THEN -1.0 ELSE 1.0 END;

  SELECT id INTO v_item_existente
  FROM alissonerp.itens_ordem_insumos
  WHERE ordem_id = p_ordem_id AND insumo_id = p_insumo_id;

  IF v_item_existente IS NOT NULL THEN
    UPDATE alissonerp.itens_ordem_insumos
    SET peso = peso + (p_qtd * v_multiplicador),
        updated_at = now()
    WHERE id = v_item_existente;
  ELSE
    INSERT INTO alissonerp.itens_ordem_insumos (ordem_id, deposito_id, insumo_id, peso)
    VALUES (p_ordem_id, p_deposito_id, p_insumo_id, p_qtd * v_multiplicador);
  END IF;
END;
$$;


--
-- Name: FUNCTION fn_criar_itens_ordem(p_ordem_id integer, p_insumo_id integer, p_deposito_id integer, p_qtd real, p_tipo_apontamento integer); Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON FUNCTION alissonerp.fn_criar_itens_ordem(p_ordem_id integer, p_insumo_id integer, p_deposito_id integer, p_qtd real, p_tipo_apontamento integer) IS 'Flow 1001: Cria/atualiza itens_ordem_insumos. Se existe soma peso, senao insere.';


--
-- Name: fn_criar_itens_ordem(integer, integer, integer, real, integer, real); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_criar_itens_ordem(p_ordem_id integer, p_insumo_id integer, p_deposito_id integer, p_qtd real, p_tipo_apontamento integer, p_peso_gramas real DEFAULT NULL::real) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_item_existente INTEGER;
  v_multiplicador  REAL;
  v_peso_real      REAL;
BEGIN
  -- Retornos (tipo 5,6) subtraem; entradas (1,2,3,4) somam
  v_multiplicador := CASE WHEN p_tipo_apontamento IN (5, 6) THEN -1.0 ELSE 1.0 END;

  -- Para pedras: p_peso_gramas (gramas reais); para metal: p_qtd ja e gramas
  v_peso_real := COALESCE(p_peso_gramas, p_qtd);

  SELECT id INTO v_item_existente
  FROM alissonerp.itens_ordem_insumos
  WHERE ordem_id = p_ordem_id AND insumo_id = p_insumo_id;

  IF v_item_existente IS NOT NULL THEN
    UPDATE alissonerp.itens_ordem_insumos
    SET peso       = peso + (v_peso_real * v_multiplicador),
        updated_at = now()
    WHERE id = v_item_existente;
  ELSE
    INSERT INTO alissonerp.itens_ordem_insumos (ordem_id, deposito_id, insumo_id, peso)
    VALUES (p_ordem_id, p_deposito_id, p_insumo_id, v_peso_real * v_multiplicador);
  END IF;
END;
$$;


--
-- Name: fn_criar_par_movimentacao(integer, real, integer, integer, integer, integer, alissonerp.enum_marcador_estoque, integer, text, integer); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_criar_par_movimentacao(p_insumo_id integer, p_quantidade real, p_dep_origem integer, p_set_origem integer, p_dep_destino integer, p_set_destino integer, p_marcador alissonerp.enum_marcador_estoque, p_ordem_id integer DEFAULT NULL::integer, p_obs text DEFAULT NULL::text, p_local_id integer DEFAULT NULL::integer) RETURNS TABLE(saida_id bigint, entrada_id bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_saida_id  bigint;
  v_entrada_id bigint;
BEGIN
  INSERT INTO alissonerp.movimentacoes_estoque
    (saida, entrada, insumo_id, deposito_id, setor_id, marcador, ordem_id, obs, local_estoque_id)
  VALUES
    (p_quantidade, 0, p_insumo_id, p_dep_origem, p_set_origem,
     p_marcador, p_ordem_id, p_obs, COALESCE(p_local_id, 1))
  RETURNING id INTO v_saida_id;

  INSERT INTO alissonerp.movimentacoes_estoque
    (saida, entrada, insumo_id, deposito_id, setor_id, marcador, ordem_id, obs, local_estoque_id)
  VALUES
    (0, p_quantidade, p_insumo_id, p_dep_destino, p_set_destino,
     p_marcador, p_ordem_id, p_obs, COALESCE(p_local_id, 1))
  RETURNING id INTO v_entrada_id;

  RETURN QUERY SELECT v_saida_id, v_entrada_id;
END;
$$;


--
-- Name: fn_criar_servico_from_pcp(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_criar_servico_from_pcp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    DECLARE
      v_tipo_ordem    VARCHAR;
      v_peso_entrada  NUMERIC;
      v_tipos_service JSONB;
    BEGIN
      SELECT tipo_ordem, COALESCE(peso_peca_servico, 0)
      INTO v_tipo_ordem, v_peso_entrada
      FROM alissonerp.ordens WHERE id = NEW.ordem_id;

      SELECT COALESCE(valor::jsonb, '["servico_venda","garantia","servico_interno"]'::jsonb)
      INTO v_tipos_service
      FROM alissonerp.configuracoes_sistema
      WHERE chave = 'service_tipos_ordem';

      IF v_tipo_ordem IS NOT NULL AND v_tipos_service ? v_tipo_ordem THEN
        INSERT INTO alissonerp.servicos
          (ordem_id, pcp_id, operador_id, peso_entrada, status)
        VALUES
          (NEW.ordem_id, NEW.id, NULL, v_peso_entrada, 'aguardando');
      END IF;

      RETURN NEW;
    END;
    $$;


