--
-- Name: fn_disparar_webhook(character varying, jsonb); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_disparar_webhook(p_nome character varying, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_url   TEXT;
  v_ativo BOOLEAN;
BEGIN
  SELECT url, ativo INTO v_url, v_ativo
  FROM alissonerp.webhook_config WHERE nome = p_nome;

  IF v_url IS NULL THEN
    RAISE NOTICE 'Webhook % nao encontrado', p_nome;
    RETURN;
  END IF;

  IF NOT v_ativo THEN
    RAISE NOTICE 'Webhook % inativo', p_nome;
    RETURN;
  END IF;

  INSERT INTO alissonerp.webhook_log (webhook_nome, payload)
  VALUES (p_nome, p_payload);

  UPDATE alissonerp.webhook_config SET
    ultimo_disparo = now(),
    total_disparos = total_disparos + 1
  WHERE nome = p_nome;
END;
$$;


--
-- Name: FUNCTION fn_disparar_webhook(p_nome character varying, p_payload jsonb); Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON FUNCTION alissonerp.fn_disparar_webhook(p_nome character varying, p_payload jsonb) IS 'Registra disparo no log + atualiza contador. HTTP feito pelo frontend.';


--
-- Name: fn_estoque_comercial_aprovar_venda(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_estoque_comercial_aprovar_venda() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'alissonerp', 'directus', 'public'
    AS $$
BEGIN
  -- Guards originais mantidos para compatibilidade com trigger existente
  IF NEW.situacao != 'aprovado' THEN RETURN NEW; END IF;
  IF OLD.situacao != 'rascunho' THEN RETURN NEW; END IF;

  -- ⛔ Aprovação NÃO move mais estoque.
  -- Reservas criadas no rascunho permanecem ativas.
  -- A saída efetivada ocorre apenas quando a venda for entregue.
  RETURN NEW;
END;
$$;


--
-- Name: fn_estoque_comercial_baixa_venda(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_estoque_comercial_baixa_venda() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'alissonerp', 'directus', 'public'
    AS $$
DECLARE
  v_config_ativo BOOLEAN;
  v_situacao     TEXT;
BEGIN
  SELECT situacao INTO v_situacao FROM alissonerp.vendas_erp WHERE id = NEW.venda_id;
  IF v_situacao = 'cancelado' THEN RETURN NEW; END IF;

  SELECT ativo INTO v_config_ativo FROM alissonerp.estoque_comercial_config WHERE produto_id = NEW.produto_id;
  IF v_config_ativo IS NULL OR v_config_ativo = false THEN RETURN NEW; END IF;

  -- rascunho, aprovado, enviado: cria reserva (estoque só é dado baixa na entrega)
  IF v_situacao IN ('rascunho', 'aprovado', 'enviado') THEN
    INSERT INTO alissonerp.reservas_estoque_comercial
      (produto_id, venda_id, item_venda_id, quantidade, local_estoque_id, status)
    VALUES
      (NEW.produto_id, NEW.venda_id, NEW.id, NEW.quantidade, 2, 'ativo');
  ELSE
    -- entregue, concluido ou qualquer outro: movimento de saída direto
    INSERT INTO alissonerp.movimentacoes_estoque_comercial
      (produto_id, tipo, quantidade, motivo, referencia_id, referencia_tipo,
       local_estoque_id, status, observacao)
    VALUES
      (NEW.produto_id, 'saida', NEW.quantidade, 'venda', NEW.venda_id, 'vendas_erp',
       2, 'efetivado', 'Venda automática - item #' || NEW.id);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_estoque_comercial_cancelamento_venda(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_estoque_comercial_cancelamento_venda() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'alissonerp', 'directus', 'public'
    AS $$
DECLARE
  v_mov            RECORD;
  v_mov_reverso_id INTEGER;
BEGIN
  IF NEW.situacao != 'cancelado' OR OLD.situacao = 'cancelado' THEN
    RETURN NEW;
  END IF;

  UPDATE alissonerp.reservas_estoque_comercial
  SET status = 'cancelado', cancelado_em = now()
  WHERE venda_id = NEW.id AND status = 'ativo';

  FOR v_mov IN
    SELECT id, produto_id, quantidade, local_estoque_id
    FROM alissonerp.movimentacoes_estoque_comercial
    WHERE referencia_id = NEW.id
      AND referencia_tipo = 'vendas_erp'
      AND tipo = 'saida'
      AND status = 'efetivado'
      AND estornado_por_id IS NULL
  LOOP
    INSERT INTO alissonerp.movimentacoes_estoque_comercial
      (produto_id, tipo, quantidade, motivo, referencia_id, referencia_tipo,
       local_estoque_id, status, estorno_de_id, observacao)
    VALUES
      (v_mov.produto_id, 'entrada', v_mov.quantidade, 'cancelamento',
       NEW.id, 'vendas_erp', v_mov.local_estoque_id, 'efetivado', v_mov.id,
       'Estorno por cancelamento da venda #' || NEW.numero_venda)
    RETURNING id INTO v_mov_reverso_id;

    UPDATE alissonerp.movimentacoes_estoque_comercial
    SET estornado_por_id = v_mov_reverso_id, status = 'estornado'
    WHERE id = v_mov.id;
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: fn_estoque_comercial_entrega_venda(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_estoque_comercial_entrega_venda() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'alissonerp', 'directus', 'public'
    AS $$
DECLARE
  v_reserva   RECORD;
  v_mov_id    INTEGER;
  v_pendentes INTEGER;
BEGIN
  IF NEW.situacao != 'entregue' THEN RETURN NEW; END IF;
  IF OLD.situacao = 'entregue'  THEN RETURN NEW; END IF;

  -- 🔒 Bloquear entrega se a venda possui ordens de reposição pendentes
  SELECT COUNT(*) INTO v_pendentes
  FROM alissonerp.ordens
  WHERE venda_id = NEW.id
    AND tipo_ordem = 'reposicao_venda'
    AND situacao IN ('criado', 'rascunho');

  IF v_pendentes > 0 THEN
    RAISE EXCEPTION 'ENTREGA_BLOCKED: Venda #% possui % ordem(ns) de reposição pendente(s). Conclua antes de marcar como entregue.',
      NEW.numero_venda, v_pendentes;
  END IF;

  -- Converter reservas ativas em saída efetivada
  FOR v_reserva IN
    SELECT id, produto_id, quantidade, local_estoque_id
    FROM alissonerp.reservas_estoque_comercial
    WHERE venda_id = NEW.id AND status = 'ativo'
  LOOP
    INSERT INTO alissonerp.movimentacoes_estoque_comercial
      (produto_id, tipo, quantidade, motivo, referencia_id, referencia_tipo,
       local_estoque_id, status, observacao)
    VALUES
      (v_reserva.produto_id, 'saida', v_reserva.quantidade, 'venda',
       NEW.id, 'vendas_erp', COALESCE(v_reserva.local_estoque_id, 2), 'efetivado',
       'Entrega venda #' || NEW.numero_venda)
    RETURNING id INTO v_mov_id;

    UPDATE alissonerp.reservas_estoque_comercial
    SET status = 'efetivado', efetivado_em = now(), movimento_id = v_mov_id
    WHERE id = v_reserva.id;
  END LOOP;

  -- 🔖 Marcar RFIDs vinculados a esta venda como vendidos
  UPDATE alissonerp.joias_rfid
  SET status = 'vendido', sold_at = now()
  WHERE venda_id = NEW.id
    AND status = 'reservado';

  RETURN NEW;
END;
$$;


--
-- Name: fn_estoque_comercial_reversao_item(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_estoque_comercial_reversao_item() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'alissonerp', 'directus', 'public'
    AS $$
DECLARE
  v_config_ativo   BOOLEAN;
  v_reserva_id     INTEGER;
  v_mov_original   RECORD;
  v_mov_reverso_id INTEGER;
BEGIN
  SELECT ativo INTO v_config_ativo FROM alissonerp.estoque_comercial_config WHERE produto_id = OLD.produto_id;
  IF v_config_ativo IS NULL OR v_config_ativo = false THEN RETURN OLD; END IF;

  SELECT id INTO v_reserva_id
  FROM alissonerp.reservas_estoque_comercial
  WHERE item_venda_id = OLD.id AND status = 'ativo'
  LIMIT 1;

  IF v_reserva_id IS NOT NULL THEN
    UPDATE alissonerp.reservas_estoque_comercial
    SET status = 'cancelado', cancelado_em = now()
    WHERE id = v_reserva_id;
    RETURN OLD;
  END IF;

  SELECT id, quantidade, local_estoque_id INTO v_mov_original
  FROM alissonerp.movimentacoes_estoque_comercial
  WHERE referencia_id = OLD.venda_id
    AND referencia_tipo = 'vendas_erp'
    AND produto_id = OLD.produto_id
    AND tipo = 'saida'
    AND status = 'efetivado'
    AND estornado_por_id IS NULL
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_mov_original.id IS NOT NULL THEN
    INSERT INTO alissonerp.movimentacoes_estoque_comercial
      (produto_id, tipo, quantidade, motivo, referencia_id, referencia_tipo,
       local_estoque_id, status, estorno_de_id, observacao)
    VALUES
      (OLD.produto_id, 'entrada', OLD.quantidade, 'estorno', OLD.venda_id, 'vendas_erp',
       v_mov_original.local_estoque_id, 'efetivado', v_mov_original.id,
       'Estorno - item removido da venda')
    RETURNING id INTO v_mov_reverso_id;

    UPDATE alissonerp.movimentacoes_estoque_comercial
    SET estornado_por_id = v_mov_reverso_id, status = 'estornado'
    WHERE id = v_mov_original.id;
  END IF;

  RETURN OLD;
END;
$$;


--
-- Name: fn_estoque_comercial_update_qtd_item(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_estoque_comercial_update_qtd_item() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'alissonerp', 'directus', 'public'
    AS $$
DECLARE
  v_config_ativo BOOLEAN;
  v_situacao     TEXT;
  v_delta        INTEGER;
  v_reserva_id   INTEGER;
BEGIN
  IF NEW.quantidade = OLD.quantidade THEN RETURN NEW; END IF;

  SELECT situacao INTO v_situacao FROM alissonerp.vendas_erp WHERE id = NEW.venda_id;
  IF v_situacao = 'cancelado' THEN RETURN NEW; END IF;

  SELECT ativo INTO v_config_ativo FROM alissonerp.estoque_comercial_config WHERE produto_id = NEW.produto_id;
  IF v_config_ativo IS NULL OR v_config_ativo = false THEN RETURN NEW; END IF;

  v_delta := NEW.quantidade - OLD.quantidade;

  IF v_situacao = 'rascunho' OR v_situacao = 'aprovado' OR v_situacao = 'enviado' THEN
    SELECT id INTO v_reserva_id
    FROM alissonerp.reservas_estoque_comercial
    WHERE item_venda_id = NEW.id AND status = 'ativo'
    LIMIT 1;

    IF v_reserva_id IS NOT NULL THEN
      UPDATE alissonerp.reservas_estoque_comercial SET quantidade = NEW.quantidade WHERE id = v_reserva_id;
    END IF;
  ELSE
    IF v_delta > 0 THEN
      INSERT INTO alissonerp.movimentacoes_estoque_comercial
        (produto_id, tipo, quantidade, motivo, referencia_id, referencia_tipo,
         local_estoque_id, status, observacao)
      VALUES
        (NEW.produto_id, 'saida', v_delta, 'venda', NEW.venda_id, 'vendas_erp',
         2, 'efetivado', 'Ajuste +' || v_delta || ' item #' || NEW.id);
    ELSIF v_delta < 0 THEN
      INSERT INTO alissonerp.movimentacoes_estoque_comercial
        (produto_id, tipo, quantidade, motivo, referencia_id, referencia_tipo,
         local_estoque_id, status, observacao)
      VALUES
        (NEW.produto_id, 'entrada', ABS(v_delta), 'devolucao', NEW.venda_id, 'vendas_erp',
         2, 'efetivado', 'Ajuste ' || v_delta || ' item #' || NEW.id);
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_gerar_conta_pagar_compra_comercial(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_gerar_conta_pagar_compra_comercial() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_fornecedor_nome TEXT;
  v_parcelas INTEGER;
  v_total NUMERIC(12,2);
  v_base NUMERIC(12,2);
  v_soma NUMERIC(12,2);
  v_diff NUMERIC(12,2);
  v_valor_parcela NUMERIC(12,2);
  i INTEGER;
BEGIN
  IF NEW.situacao != 'concluido' OR OLD.situacao = 'concluido' THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM alissonerp.contas_pagar cp
    WHERE cp.compra_comercial_id = NEW.id
  ) THEN
    RETURN NEW;
  END IF;

  SELECT nome INTO v_fornecedor_nome
  FROM public.contatos
  WHERE id_contato = NEW.fornecedor_id;

  v_parcelas := GREATEST(COALESCE(NEW.qtd_parcelas, 1), 1);
  v_total := COALESCE(NEW.total, 0);

  v_base := ROUND((v_total / v_parcelas)::numeric, 2);
  v_soma := ROUND((v_base * v_parcelas)::numeric, 2);
  v_diff := ROUND((v_total - v_soma)::numeric, 2);

  FOR i IN 1..v_parcelas LOOP
    v_valor_parcela := v_base;
    IF i = v_parcelas THEN
      -- Ajuste de centavos apenas na última parcela para manter a soma idêntica ao total.
      v_valor_parcela := ROUND((v_base + v_diff)::numeric, 2);
    END IF;

    INSERT INTO alissonerp.contas_pagar (
      descricao,
      fornecedor_id,
      fornecedor_nome,
      compra_comercial_id,
      valor,
      data_vencimento,
      situacao,
      categoria,
      created_by,
      obs
    ) VALUES (
      'Compra Comercial #' || NEW.id || ' - Parcela ' || i || '/' || v_parcelas,
      NEW.fornecedor_id,
      v_fornecedor_nome,
      NEW.id,
      v_valor_parcela,
      ((NEW.primeiro_vencimento::date + ((i - 1) || ' month')::interval))::date,
      'pendente',
      'compra_comercial',
      NEW.created_by,
      'Gerado automaticamente na conclusão da compra comercial #' || NEW.id
    );
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: fn_handle_new_user(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO alissonerp.usuarios (id, email, nome, role)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(
      NEW.raw_user_meta_data->>'nome',
      NEW.raw_user_meta_data->>'full_name',
      split_part(NEW.email, '@', 1)
    ),
    COALESCE(NEW.raw_user_meta_data->>'role', 'ourives')
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$$;


