--
-- Name: fn_mirror_movimento_to_sle(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_mirror_movimento_to_sle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    DECLARE
      v_sle_id BIGINT;
    BEGIN
      INSERT INTO alissonerp.stock_ledger_entry (
        item_id, item_type, warehouse_id,
        actual_qty,
        voucher_type, voucher_id,
        obs, created_by, posting_date, posting_time
      ) VALUES (
        NEW.produto_id, 'produto', NEW.local_estoque_id,
        CASE WHEN NEW.tipo = 'entrada' THEN NEW.quantidade ELSE -NEW.quantidade END,
        CASE
          WHEN NEW.motivo = 'venda' THEN 'venda'
          WHEN NEW.motivo IN ('transferencia_saida','transferencia_entrada') THEN 'transferencia'
          WHEN NEW.motivo = 'devolucao' THEN 'devolucao'
          WHEN NEW.motivo = 'inventario' THEN 'inventario'
          WHEN NEW.motivo = 'estorno' THEN 'reconciliacao'
          WHEN NEW.motivo = 'ajuste_entrada' THEN 'ajuste_entrada'
          WHEN NEW.motivo = 'ajuste_saida' THEN 'ajuste_saida'
          WHEN NEW.motivo = 'producao_auto' THEN 'producao_auto'
          WHEN NEW.motivo IN ('reservado_conversao','virou_peso') THEN 'ordem_producao'
          WHEN NEW.motivo = 'recusado_conversao' THEN 'reconciliacao'
          WHEN NEW.motivo IN ('conversao_sku_ida','conversao_sku_volta') THEN 'transferencia'
          WHEN NEW.motivo IN ('conversao_sku_consumo','conversao_sku_producao') THEN 'ordem_producao'
          ELSE 'manual'
        END,
        COALESCE(NEW.referencia_id, NEW.id),
        NEW.observacao,
        COALESCE(NEW.created_by, '00000000-0000-0000-0000-000000000000'::uuid),
        NEW.created_at::DATE,
        NEW.created_at::TIME
      ) RETURNING id INTO v_sle_id;
      RETURN NEW;
    END;
    $$;


--
-- Name: fn_ponte_directus_para_alissonerp(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_ponte_directus_para_alissonerp() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_ordem_id  INTEGER;
  v_audit_id  INTEGER;
BEGIN
  -- Guard: só processar ordens com situacao = '2' (Criado)
  IF NEW.situacao != '2' THEN
    RETURN NEW;
  END IF;

  -- UPSERT da ordem
  INSERT INTO alissonerp.ordens (
    numero_ordem, cliente_id, vendedor_id, pedido_id,
    tipo_ordem,
    data_entrega, peso_metal_negociado, peso_metal_externo,
    itens_para_fabricacao,
    situacao, status, rota,
    tipo_controle, setor_atual, local_atual,
    distribuicao_id, protocolo_loja,
    id_ordem_relacionada, id_asana,
    data_conclusao, created_at, updated_at,
    directus_ordem_id
  ) VALUES (
    NEW.numero_ordem,
    NEW.cliente_id,
    NEW.vendedor_id,
    NEW.pedido_id,
    CASE NEW.tipo_ordem
      WHEN '1' THEN 'producao' WHEN '2' THEN 'reparo'  WHEN '3' THEN 'ajuste'
      WHEN '4' THEN 'banho'    WHEN '5' THEN 'gravacao' WHEN '6' THEN 'reposicao'
      WHEN '7' THEN 'outro'    ELSE       'outro'
    END::alissonerp.enum_tipo_ordem,
    NEW.data_entrega,
    COALESCE(NEW.peso_metal_negocido, 0),
    COALESCE(NEW.peso_metal_externo, 0),
    NEW.itens_para_fabricacao,
    'criado'::alissonerp.enum_situacao_ordem,
    CASE NEW.status
      WHEN '1' THEN 'aguardando' WHEN '2' THEN 'em_andamento' WHEN '3' THEN 'concluido'
      ELSE 'aguardando'
    END::alissonerp.enum_status_ordem,
    CASE NEW.rota WHEN '1' THEN 'pcp' WHEN '2' THEN 'protocolo' ELSE NULL END::alissonerp.enum_rota_ordem,
    NEW.tipo_controle,
    NEW.setor_atual,
    NEW.local_atual::integer,
    NEW.distribuicao_id,
    COALESCE(NEW.protocolo_loja::boolean, false),
    NEW.id_ordem_relacionada::integer,
    NEW.id_asana,
    NEW.data_conclusao,
    COALESCE(NEW.date_created, now()),
    now(),
    NEW.id
  )
  ON CONFLICT (directus_ordem_id) DO UPDATE SET
    peso_metal_externo    = EXCLUDED.peso_metal_externo,
    itens_para_fabricacao = EXCLUDED.itens_para_fabricacao,
    status                = EXCLUDED.status,
    rota                  = EXCLUDED.rota,
    setor_atual           = EXCLUDED.setor_atual,
    local_atual           = EXCLUDED.local_atual,
    updated_at            = now()
  RETURNING id INTO v_ordem_id;

  -- Auditoria loja automática: somente em INSERT e se não existe auditoria ativa
  IF TG_OP = 'INSERT' AND v_ordem_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM alissonerp.auditorias
      WHERE ordem_id = v_ordem_id
        AND tipo_auditoria = 'loja'
        AND situacao != 'reprovado'
    ) THEN
      INSERT INTO alissonerp.auditorias (
        situacao, tipo_auditoria, rota_processo, ordem_id,
        peso_negociado, dados_ordem
      ) VALUES (
        'pendente', 'loja', 'entrada_ordem', v_ordem_id,
        COALESCE(NEW.peso_metal_negocido, 0),
        jsonb_build_object(
          'numero_ordem',     NEW.numero_ordem,
          'tipo_ordem',       NEW.tipo_ordem,
          'rota',             NEW.rota,
          'peso_negociado',   NEW.peso_metal_negocido,
          'peso_externo',     NEW.peso_metal_externo,
          'cliente_id',       NEW.cliente_id,
          'vendedor_id',      NEW.vendedor_id,
          'data_entrega',     NEW.data_entrega::text,
          'itens_fabricacao', NEW.itens_para_fabricacao
        )
      ) RETURNING id INTO v_audit_id;

      -- Aprovação automática — dispara fn_processar_auditoria (cria PCP/saida_ordem)
      UPDATE alissonerp.auditorias
      SET situacao       = 'aprovado',
          data_conclusao = now(),
          parecer        = 'Aprovação automática — PDV'
      WHERE id = v_audit_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_ponte_directus_para_alissonerp(); Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON FUNCTION alissonerp.fn_ponte_directus_para_alissonerp() IS 'TEMPORÁRIO: Copia ordens situacao=2 do directus→alissonerp + auditoria loja. Inclui ficha_tecnica_id (v030). Remover quando migrar PDV.';


--
-- Name: fn_prevent_negative_sle(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_prevent_negative_sle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.voucher_type = 'inventario' THEN
    RETURN NEW;
  END IF;
  IF (SELECT COALESCE(SUM(actual_qty), 0) + NEW.actual_qty
      FROM alissonerp.stock_ledger_entry
      WHERE item_id = NEW.item_id
        AND item_type = NEW.item_type
        AND warehouse_id = NEW.warehouse_id
        AND is_cancelled = false) < 0
  THEN
    RAISE EXCEPTION 'STOCK_NEGATIVE: Saldo insuficiente no almoxarifado. Item=%, Warehouse=%',
      NEW.item_id, NEW.warehouse_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_prevent_sle_delete(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_prevent_sle_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'STOCK_IMMUTABLE: Nao pode deletar. Use estorno ou reconciliacao.';
END;
$$;


--
-- Name: fn_processar_apontamento_dist(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_processar_apontamento_dist() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_marcador   alissonerp.enum_marcador_estoque;
  v_dep_almox  INTEGER := 1;
  v_peso_pedra REAL;
  v_peso_ct    NUMERIC(10,4);
BEGIN
  IF NEW.insumo_id IS NOT NULL THEN
    SELECT COALESCE(peso_pedra, 0) INTO v_peso_pedra
    FROM alissonerp.insumos WHERE id = NEW.insumo_id;
  ELSE
    v_peso_pedra := 0;
  END IF;

  CASE NEW.tipo_apontamento_id

    -- TIPO 1: Aditivo metal (ADD) ??? Dep1 ??? DepDist
    WHEN 1 THEN
      v_marcador := 'ADD';
      PERFORM alissonerp.fn_criar_par_movimentacao(
        NEW.insumo_id, NEW.qtd,
        v_dep_almox, NULL,
        NEW.deposito_id, NEW.setor_id,
        v_marcador, NULL, NULL, 1
      );
      UPDATE alissonerp.distribuicoes
      SET total_metal = total_metal + NEW.qtd, updated_at = now()
      WHERE id = NEW.distribuicao_id;

    -- TIPO 2: Entrada metal (EIMD) ??? Dep1 ??? DepDist
    WHEN 2 THEN
      v_marcador := 'EIMD';
      PERFORM alissonerp.fn_criar_par_movimentacao(
        NEW.insumo_id, NEW.qtd,
        v_dep_almox, NULL,
        NEW.deposito_id, NEW.setor_id,
        v_marcador, NULL, NULL, 1
      );
      UPDATE alissonerp.distribuicoes
      SET total_metal = total_metal + NEW.qtd, updated_at = now()
      WHERE id = NEW.distribuicao_id;

    -- TIPO 3: Entrada pedra (EPD) ??? Dep1 ??? DepDist
    WHEN 3 THEN
      v_marcador := 'EPD';
      v_peso_ct  := NEW.peso_ct;
      IF v_peso_ct IS NOT NULL AND v_peso_ct > 0 THEN
        -- Novo: CE em ct
        PERFORM alissonerp.fn_criar_par_movimentacao(
          NEW.insumo_id, v_peso_ct::REAL,
          v_dep_almox, NULL,
          NEW.deposito_id, NEW.setor_id,
          v_marcador, NULL, NULL, 1
        );
        UPDATE alissonerp.distribuicoes SET
          total_pedras_ct = COALESCE(total_pedras_ct, 0) + v_peso_ct,
          total_pedras_un = total_pedras_un + NEW.qtd,
          total_pedras_g  = total_pedras_g  + (v_peso_pedra * NEW.qtd),
          updated_at      = now()
        WHERE id = NEW.distribuicao_id;
      ELSE
        -- Backward compat: CE em gramas
        PERFORM alissonerp.fn_criar_par_movimentacao(
          NEW.insumo_id, NEW.qtd,
          v_dep_almox, NULL,
          NEW.deposito_id, NEW.setor_id,
          v_marcador, NULL, NULL, 1
        );
        UPDATE alissonerp.distribuicoes SET
          total_pedras_un = total_pedras_un + NEW.qtd,
          total_pedras_g  = total_pedras_g  + (v_peso_pedra * NEW.qtd),
          updated_at      = now()
        WHERE id = NEW.distribuicao_id;
      END IF;

    -- TIPO 5: Retorno metal (RMD) ??? DepDist ??? Dep1
    WHEN 5 THEN
      v_marcador := 'RMD';
      PERFORM alissonerp.fn_criar_par_movimentacao(
        NEW.insumo_id, NEW.qtd,
        NEW.deposito_id, NEW.setor_id,
        v_dep_almox, NULL,
        v_marcador, NULL, NULL, 1
      );
      UPDATE alissonerp.distribuicoes
      SET retorno_metal = retorno_metal + NEW.qtd, updated_at = now()
      WHERE id = NEW.distribuicao_id;

    -- TIPO 6: Retorno pedra (RPD) ??? DepDist ??? Dep1
    WHEN 6 THEN
      v_marcador := 'RPD';
      v_peso_ct  := NEW.peso_ct;
      IF v_peso_ct IS NOT NULL AND v_peso_ct > 0 THEN
        -- Novo: CE em ct (retorno)
        PERFORM alissonerp.fn_criar_par_movimentacao(
          NEW.insumo_id, v_peso_ct::REAL,
          NEW.deposito_id, NEW.setor_id,
          v_dep_almox, NULL,
          v_marcador, NULL, NULL, 1
        );
        UPDATE alissonerp.distribuicoes SET
          total_pedras_ct = COALESCE(total_pedras_ct, 0) - v_peso_ct,
          total_pedras_un = total_pedras_un - NEW.qtd,
          total_pedras_g  = total_pedras_g  - (v_peso_pedra * NEW.qtd),
          updated_at      = now()
        WHERE id = NEW.distribuicao_id;
      ELSE
        -- Backward compat
        PERFORM alissonerp.fn_criar_par_movimentacao(
          NEW.insumo_id, NEW.qtd,
          NEW.deposito_id, NEW.setor_id,
          v_dep_almox, NULL,
          v_marcador, NULL, NULL, 1
        );
        UPDATE alissonerp.distribuicoes SET
          total_pedras_un = total_pedras_un - NEW.qtd,
          total_pedras_g  = total_pedras_g  - (v_peso_pedra * NEW.qtd),
          updated_at      = now()
        WHERE id = NEW.distribuicao_id;
      END IF;

    -- TIPO 8: Entrada outros insumos (EOID) ??? sa??da direta do almox
    WHEN 8 THEN
      v_marcador := 'EOID';
      INSERT INTO alissonerp.movimentacoes_estoque
        (saida, entrada, insumo_id, deposito_id, marcador, local_estoque_id)
      VALUES
        (NEW.qtd, 0, NEW.insumo_id, v_dep_almox, v_marcador, 1);

    -- TIPO 9: Ocorr??ncia distribui????o ??? sem CE
    WHEN 9 THEN
      NULL;

    ELSE
      RAISE NOTICE 'Tipo apontamento % nao tratado na distribuicao', NEW.tipo_apontamento_id;

  END CASE;

  -- Flow 1011: upsert item da distribui????o (tipos 1-6) ??? inalterado
  IF NEW.tipo_apontamento_id BETWEEN 1 AND 6 AND NEW.insumo_id IS NOT NULL THEN
    PERFORM alissonerp.fn_criar_item_distribuicao(
      NEW.distribuicao_id, NEW.insumo_id, NEW.deposito_id, NEW.qtd, NEW.tipo_apontamento_id
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_processar_apontamento_dist(); Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON FUNCTION alissonerp.fn_processar_apontamento_dist() IS 'Flow 1007: Branch tipo 1-9 com CE marcadores dist (ADD,EIMD,EPD,RMD,RPD,EOID) + Flow 1011.';


--
-- Name: fn_processar_apontamento_pcp(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_processar_apontamento_pcp() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_ordem_id            INTEGER;
  v_marcador            alissonerp.enum_marcador_estoque;
  v_peso_pedra_unitario REAL;
  v_dep_almox           INTEGER := 1;
  v_peso_ct             NUMERIC(10,4);
  v_peso_gramas_itens   REAL;
BEGIN
  SELECT p.ordem_id INTO v_ordem_id
  FROM alissonerp.pcp p WHERE p.id = NEW.pcp_id;

  IF v_ordem_id IS NULL THEN
    RAISE EXCEPTION 'PCP % nao encontrado ou sem ordem vinculada', NEW.pcp_id;
  END IF;

  IF NEW.insumo_id IS NOT NULL THEN
    SELECT COALESCE(peso_pedra, 0) INTO v_peso_pedra_unitario
    FROM alissonerp.insumos WHERE id = NEW.insumo_id;
  ELSE
    v_peso_pedra_unitario := 0;
  END IF;

  CASE NEW.tipo_apontamento_id

    WHEN 1 THEN
      v_marcador := 'AD';
      PERFORM alissonerp.fn_criar_par_movimentacao(
        NEW.insumo_id, NEW.qtd,
        v_dep_almox, NULL,
        NEW.deposito_id, NEW.setor_id,
        v_marcador, v_ordem_id, NULL, 1
      );
      UPDATE alissonerp.pcp SET total_metal = total_metal + NEW.qtd WHERE id = NEW.pcp_id;

    WHEN 2 THEN
      v_marcador := 'EM';
      PERFORM alissonerp.fn_criar_par_movimentacao(
        NEW.insumo_id, NEW.qtd,
        v_dep_almox, NULL,
        NEW.deposito_id, NEW.setor_id,
        v_marcador, v_ordem_id, NULL, 1
      );
      UPDATE alissonerp.pcp SET total_metal = total_metal + NEW.qtd WHERE id = NEW.pcp_id;

    WHEN 3 THEN
      v_marcador := 'EP';
      v_peso_ct  := NEW.peso_ct;
      IF v_peso_ct IS NOT NULL AND v_peso_ct > 0 THEN
        PERFORM alissonerp.fn_criar_par_movimentacao(
          NEW.insumo_id, v_peso_ct::REAL,
          v_dep_almox, NULL,
          NEW.deposito_id, NEW.setor_id,
          v_marcador, v_ordem_id, NULL, 1
        );
        UPDATE alissonerp.pcp SET
          total_pedras_ct = COALESCE(total_pedras_ct, 0) + v_peso_ct,
          total_pedras_un = total_pedras_un + NEW.qtd,
          total_pedras_g  = total_pedras_g  + (COALESCE(v_peso_pedra_unitario, 0) * NEW.qtd)
        WHERE id = NEW.pcp_id;
      ELSE
        PERFORM alissonerp.fn_criar_par_movimentacao(
          NEW.insumo_id, NEW.qtd,
          v_dep_almox, NULL,
          NEW.deposito_id, NEW.setor_id,
          v_marcador, v_ordem_id, NULL, 1
        );
        UPDATE alissonerp.pcp SET
          total_pedras_un = total_pedras_un + NEW.qtd,
          total_pedras_g  = total_pedras_g  + (COALESCE(v_peso_pedra_unitario, 0) * NEW.qtd)
        WHERE id = NEW.pcp_id;
      END IF;
      IF COALESCE(v_peso_pedra_unitario, 0) > 0 THEN
        INSERT INTO alissonerp.pedras_ordens (ordem_id, deposito_id, peso, peso_pedra, qtd_pedras)
        VALUES (v_ordem_id, NEW.deposito_id, v_peso_pedra_unitario * NEW.qtd, v_peso_pedra_unitario, NEW.qtd);
      END IF;

    WHEN 4 THEN
      v_marcador := 'BI';
      PERFORM alissonerp.fn_criar_par_movimentacao(
        NEW.insumo_id, NEW.qtd,
        NEW.deposito_id, NEW.setor_id,
        v_dep_almox, NULL,
        v_marcador, v_ordem_id, NULL, 1
      );

    WHEN 5 THEN
      v_marcador := 'RM';
      PERFORM alissonerp.fn_criar_par_movimentacao(
        NEW.insumo_id, NEW.qtd,
        NEW.deposito_id, NEW.setor_id,
        v_dep_almox, NULL,
        v_marcador, v_ordem_id, NULL, 1
      );
      UPDATE alissonerp.pcp SET retorno_metal = retorno_metal + NEW.qtd WHERE id = NEW.pcp_id;

    WHEN 6 THEN
      v_marcador := 'RP';
      v_peso_ct  := NEW.peso_ct;
      IF v_peso_ct IS NOT NULL AND v_peso_ct > 0 THEN
        PERFORM alissonerp.fn_criar_par_movimentacao(
          NEW.insumo_id, v_peso_ct::REAL,
          NEW.deposito_id, NEW.setor_id,
          v_dep_almox, NULL,
          v_marcador, v_ordem_id, NULL, 1
        );
        UPDATE alissonerp.pcp SET
          total_pedras_ct = COALESCE(total_pedras_ct, 0) - v_peso_ct,
          total_pedras_un = total_pedras_un - NEW.qtd,
          total_pedras_g  = total_pedras_g  - (COALESCE(v_peso_pedra_unitario, 0) * NEW.qtd)
        WHERE id = NEW.pcp_id;
      ELSE
        PERFORM alissonerp.fn_criar_par_movimentacao(
          NEW.insumo_id, NEW.qtd,
          NEW.deposito_id, NEW.setor_id,
          v_dep_almox, NULL,
          v_marcador, v_ordem_id, NULL, 1
        );
        UPDATE alissonerp.pcp SET
          total_pedras_un = total_pedras_un - NEW.qtd,
          total_pedras_g  = total_pedras_g  - (COALESCE(v_peso_pedra_unitario, 0) * NEW.qtd)
        WHERE id = NEW.pcp_id;
      END IF;

    WHEN 7 THEN
      NULL;

    ELSE
      RAISE NOTICE 'Tipo apontamento % nao tratado no PCP', NEW.tipo_apontamento_id;
  END CASE;

  -- Flow 1001: atualizar itens_ordem_insumos para tipos 1-6
  -- Para pedras (3,6): p_peso_gramas = qtd x peso_pedra_unitario (gramas)
  -- Para metal (1,2,4,5): p_peso_gramas=NULL -> COALESCE usa p_qtd (ja e gramas)
  IF NEW.tipo_apontamento_id BETWEEN 1 AND 6 AND NEW.insumo_id IS NOT NULL THEN
    v_peso_gramas_itens := CASE
      WHEN NEW.tipo_apontamento_id IN (3, 6) AND COALESCE(v_peso_pedra_unitario, 0) > 0
        THEN v_peso_pedra_unitario * NEW.qtd
      ELSE NULL
    END;
    PERFORM alissonerp.fn_criar_itens_ordem(
      v_ordem_id, NEW.insumo_id, NEW.deposito_id, NEW.qtd, NEW.tipo_apontamento_id,
      v_peso_gramas_itens
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_processar_apontamento_pcp(); Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON FUNCTION alissonerp.fn_processar_apontamento_pcp() IS 'Flow 1000: Branch por tipo 1-7, CE dupla-entrada, atualiza totais PCP, chama fn_criar_itens_ordem.';


--
-- Name: fn_processar_aprovacao_cartao(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_processar_aprovacao_cartao() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN
      IF NEW.tipo = 'cartao_desconto' AND NEW.status = 'aprovada'
         AND (OLD.status IS DISTINCT FROM 'aprovada')
         AND NEW.venda_id IS NOT NULL THEN
        UPDATE alissonerp.vendas_erp
        SET aprovacao_credito_tarefa_id = NULL,
            desconto_cartao_aprovado_por = NEW.responsavel_id,
            desconto_cartao_aprovado_em  = NOW(),
            updated_at = NOW()
        WHERE id = NEW.venda_id
          AND desconto_cartao_aprovado_por IS NULL;
      END IF;
      RETURN NEW;
    END;
    $$;


--
-- Name: fn_processar_auditoria(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_processar_auditoria() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
    DECLARE
      v_ordem          RECORD;
      v_nova_ordem_id  INTEGER;
      v_saida_id       INTEGER;
    BEGIN
      IF TG_OP = 'UPDATE' AND OLD.situacao = NEW.situacao THEN RETURN NEW; END IF;
      IF NEW.ordem_id IS NULL THEN RETURN NEW; END IF;

      IF NEW.situacao = 'aprovado' THEN
        NEW.data_conclusao := COALESCE(NEW.data_conclusao, now());

        IF NEW.tipo_auditoria = 'loja' THEN
          SELECT * INTO v_ordem FROM alissonerp.ordens WHERE id = NEW.ordem_id;

          IF v_ordem.rota = 'pcp' THEN
            INSERT INTO alissonerp.saidas_ordem (ordem_id)
            VALUES (NEW.ordem_id) RETURNING id INTO v_saida_id;

            INSERT INTO alissonerp.pcp (
              ordem_id, etapas, saida_ordem_id, metal_externo,
              total_metal, retorno_metal, total_pedras_un, total_pedras_g,
              total_geral_outros_pesos, total_outros_pesos_g
            ) VALUES (
              NEW.ordem_id, 'novas_ordens', v_saida_id,
              COALESCE(v_ordem.peso_metal_externo, 0),
              0, 0, 0, 0, 0, 0
            );

            UPDATE alissonerp.ordens
            SET status = 'em_andamento', updated_at = now()
            WHERE id = NEW.ordem_id;

          ELSE
            UPDATE alissonerp.ordens
            SET status = 'aguardando', updated_at = now()
            WHERE id = NEW.ordem_id;
          END IF;

        END IF;
        RETURN NEW;
      END IF;

      IF NEW.situacao = 'reprovado' THEN
        IF NEW.motivo_reprovacao IS NULL OR TRIM(NEW.motivo_reprovacao) = '' THEN
          RAISE EXCEPTION 'Motivo de reprovação é obrigatório';
        END IF;
        NEW.data_conclusao := COALESCE(NEW.data_conclusao, now());

        IF NEW.tipo_auditoria = 'loja' THEN
          UPDATE alissonerp.ordens SET
            situacao          = 'rascunho'::alissonerp.enum_situacao_ordem,
            status            = 'aguardando'::alissonerp.enum_status_ordem,
            origem_reprovacao = 'auditoria_loja',
            updated_at        = now()
          WHERE id = NEW.ordem_id;

        ELSIF NEW.tipo_auditoria = 'fabrica' THEN
          SELECT * INTO v_ordem FROM alissonerp.ordens WHERE id = NEW.ordem_id;

          INSERT INTO alissonerp.ordens (
            numero_ordem, cliente_id, vendedor_id,
            tipo_ordem, situacao, status, rota,
            peso_metal_negociado, id_ordem_relacionada,
            origem_reprovacao
          ) VALUES (
            COALESCE(v_ordem.numero_ordem, '#' || v_ordem.id::text) || '-RET',
            v_ordem.cliente_id,
            v_ordem.vendedor_id,
            'servico_venda'::alissonerp.enum_tipo_ordem,
            'criado'::alissonerp.enum_situacao_ordem,
            'aguardando'::alissonerp.enum_status_ordem,
            'pcp'::alissonerp.enum_rota_ordem,
            v_ordem.peso_metal_negociado,
            v_ordem.id,
            'auditoria_fabrica'
          ) RETURNING id INTO v_nova_ordem_id;

          INSERT INTO alissonerp.saidas_ordem (ordem_id)
          VALUES (v_nova_ordem_id)
          RETURNING id INTO v_saida_id;

          INSERT INTO alissonerp.pcp (
            ordem_id, etapas, saida_ordem_id,
            total_metal, retorno_metal, total_pedras_un, total_pedras_g,
            total_geral_outros_pesos, total_outros_pesos_g, metal_externo
          ) VALUES (
            v_nova_ordem_id, 'novas_ordens', v_saida_id,
            0, 0, 0, 0, 0, 0, 0
          );

          NEW.ordem_retrabalho_id := v_nova_ordem_id;
        END IF;
        RETURN NEW;
      END IF;

      IF NEW.situacao = 'pendenciado' THEN RETURN NEW; END IF;
      RETURN NEW;
    END;
    $$;


--
-- Name: FUNCTION fn_processar_auditoria(); Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON FUNCTION alissonerp.fn_processar_auditoria() IS 'Loja aprovada→libera produção. Fábrica aprovada→libera volta. Loja reprovada→rascunho. Fábrica reprovada→retrabalho (tipo=servico).';


--
-- Name: fn_processar_conversao(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_processar_conversao() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_ordem      RECORD;
  v_tarefa_id  INTEGER;
BEGIN
  SELECT numero_ordem, created_by INTO v_ordem
  FROM alissonerp.ordens WHERE id = NEW.ordem_id;

  INSERT INTO alissonerp.tarefas (
    titulo, descricao, responsavel_id, criado_por,
    prioridade, status, tipo, ordem_id, tags
  ) VALUES (
    'Aprovacao de Conversao de Estoque - Ordem ' || COALESCE(v_ordem.numero_ordem, '#' || NEW.ordem_id),
    'CONVERSAO DE ESTOQUE COMERCIAL PARA METAL' || E'\n\n' ||
    'Ordem: ' || COALESCE(v_ordem.numero_ordem, '#' || NEW.ordem_id) || E'\n' ||
    'Peso Total: ' || NEW.peso_total || 'g' || E'\n' ||
    'Quantidade Total: ' || NEW.quantidade_total || ' pecas' || E'\n\n' ||
    'Produtos: (aguardando insercao dos itens)' || E'\n\n' ||
    'ATENCAO: Aprovacao necessaria para liberar para protocolo.' || E'\n' ||
    'Aprovar: libera para protocolo de ida' || E'\n' ||
    'Rejeitar: produtos retornam ao estoque',
    COALESCE(
      (SELECT id FROM alissonerp.usuarios WHERE role = 'admin' AND email LIKE '%alisson%' LIMIT 1),
      (SELECT id FROM alissonerp.usuarios WHERE role = 'admin' LIMIT 1)
    ),
    NEW.created_by,
    'alta',
    'aguardando_aprovacao',
    'conversao',
    NEW.ordem_id,
    ARRAY['conversao', 'estoque', 'aprovacao']
  )
  RETURNING id INTO v_tarefa_id;

  UPDATE alissonerp.conversoes_estoque
  SET tarefa_aprovacao_id = v_tarefa_id
  WHERE id = NEW.id;

  RETURN NEW;
END;
$$;


--
-- Name: fn_processar_conversao_sku(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_processar_conversao_sku() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_ordem    RECORD;
  v_origem   RECORD;
  v_destino  RECORD;
  v_tarefa_id INTEGER;
  v_local_nome TEXT;
BEGIN
  SELECT numero_ordem, created_by INTO v_ordem
  FROM alissonerp.ordens WHERE id = NEW.ordem_id;

  SELECT nome, sku INTO v_origem
  FROM public.produtos WHERE id_produto = NEW.sku_origem_id;

  SELECT nome, sku INTO v_destino
  FROM public.produtos WHERE id_produto = NEW.sku_destino_id;

  SELECT nome INTO v_local_nome
  FROM alissonerp.locais_estoque WHERE id = NEW.local_origem_id;

  INSERT INTO alissonerp.tarefas (
    titulo, descricao, responsavel_id, criado_por,
    prioridade, status, tipo, ordem_id, tags
  ) VALUES (
    'Aprovação de Conversão SKU — Ordem ' || COALESCE(v_ordem.numero_ordem, '#' || NEW.ordem_id),
    '🔄 **Conversão de SKU**' || E'\n\n' ||
    '**Origem:** ' || COALESCE(v_origem.nome, 'N/D') || ' (SKU: ' || COALESCE(v_origem.sku, 'N/D') || ')' || E'\n' ||
    '**Peso:** ' || NEW.sku_origem_peso || 'g' || E'\n' ||
    '**Quantidade:** ' || NEW.sku_origem_quantidade || E'\n' ||
    '**Local:** ' || COALESCE(v_local_nome, 'N/D') || E'\n\n' ||
    '**Destino:** ' || COALESCE(v_destino.nome, 'N/D') || ' (SKU: ' || COALESCE(v_destino.sku, 'N/D') || ')' || E'\n' ||
    '**Quantidade Desejada:** ' || NEW.sku_destino_quantidade_desejada || E'\n\n' ||
    '🔴 **Aprovação necessária para liberar para protocolo.**' || E'\n' ||
    '✅ **Aprovar** → libera para protocolo de ida' || E'\n' ||
    '❌ **Rejeitar** → SKU retorna ao estoque',
    COALESCE(
      (SELECT id FROM alissonerp.usuarios WHERE role = 'admin' AND email LIKE '%alisson%' LIMIT 1),
      (SELECT id FROM alissonerp.usuarios WHERE role = 'admin' LIMIT 1)
    ),
    NEW.created_by,
    'alta',
    'aguardando_aprovacao',
    'conversao_sku',
    NEW.ordem_id,
    ARRAY['conversao_sku', 'estoque', 'aprovacao']
  )
  RETURNING id INTO v_tarefa_id;

  UPDATE alissonerp.conversoes_sku
  SET tarefa_aprovacao_id = v_tarefa_id
  WHERE id = NEW.id;

  RETURN NEW;
END;
$$;


--
-- Name: fn_processar_fechamento_dist(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_processar_fechamento_dist() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_pcp_id    INTEGER;
  v_dep_dist  INTEGER;
BEGIN
  -- Guard: só processar quando peso é preenchido pela primeira vez
  IF NEW.peso IS NULL OR NEW.peso <= 0 THEN
    RETURN NEW;
  END IF;
  -- Para UPDATE: não reprocessar se já tinha peso > 0 (evita duplo acúmulo)
  IF TG_OP = 'UPDATE' AND OLD.peso IS NOT NULL AND OLD.peso > 0 THEN
    RETURN NEW;
  END IF;

  -- Guard v2: verificar se já existe processamento anterior para (distribuicao_id, ordem_id)
  -- O índice único acima previne o INSERT, mas este guard protege em casos de UPSERT ou bypass
  IF TG_OP = 'INSERT' THEN
    -- O índice único já vai rejeitar INSERT duplicado com erro
    -- Este bloco é documentação do comportamento esperado
    NULL;
  END IF;

  -- Buscar PCP ativo da ordem
  SELECT id INTO v_pcp_id
  FROM alissonerp.pcp
  WHERE ordem_id = NEW.ordem_id
    AND etapas NOT IN ('concluido', 'cancelado')
  ORDER BY id DESC
  LIMIT 1;

  IF v_pcp_id IS NULL THEN
    RAISE NOTICE 'Sem PCP ativo para ordem %, ignorando acumulo', NEW.ordem_id;
    RETURN NEW;
  END IF;

  -- Buscar depósito da distribuição (do primeiro apontamento)
  SELECT deposito_id INTO v_dep_dist
  FROM alissonerp.apontamentos_distribuicao
  WHERE distribuicao_id = NEW.distribuicao_id
  LIMIT 1;

  -- ═══ ACUMULAR NO PCP — SOMA, NÃO SUBSTITUI ═══
  UPDATE alissonerp.pcp SET
    total_metal     = total_metal     + COALESCE(NEW.pmc, 0),
    total_pedras_un = total_pedras_un + COALESCE(NEW.total_pedras_un, 0),
    total_pedras_g  = total_pedras_g  + COALESCE(NEW.total_pedras_g, 0),
    updated_at      = now()
  WHERE id = v_pcp_id;

  -- CE marcador TEDD (dep distribuição → dep almoxarifado) usando Ouro como proxy
  IF v_dep_dist IS NOT NULL THEN
    PERFORM alissonerp.fn_criar_par_movimentacao(
      1, NEW.peso,
      v_dep_dist, NULL,
      1, NULL,
      'TEDD', NEW.ordem_id,
      'Fechamento distribuicao #' || NEW.distribuicao_id::text || ' → PCP'
    );
  END IF;

  -- Mover ordem para almoxarifado (local_atual = 1)
  UPDATE alissonerp.ordens
  SET local_atual = 1, updated_at = now()
  WHERE id = NEW.ordem_id;

  -- Criar transferência vazia para a ordem (registra movimentação no histórico)
  INSERT INTO alissonerp.transferencias_ordem (pcp_id, ordem_id)
  VALUES (v_pcp_id, NEW.ordem_id);

  -- Copiar itens distribuição → itens_ordem_insumos
  INSERT INTO alissonerp.itens_ordem_insumos (ordem_id, deposito_id, insumo_id, peso)
  SELECT NEW.ordem_id, id_item.deposito_id, id_item.insumo_id, id_item.peso
  FROM alissonerp.itens_distribuicao id_item
  WHERE id_item.distribuicao_id = NEW.distribuicao_id
    AND id_item.peso > 0;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_processar_fechamento_dist(); Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON FUNCTION alissonerp.fn_processar_fechamento_dist() IS 'Flow 1013: ACUMULA no PCP (soma!), CE TEDD, move ordem → dep1, cria transferencia + copia itens.';


--
-- Name: fn_processar_lancamento_avulso(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_processar_lancamento_avulso() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_dep_almox   INTEGER := 1;
  v_dep_destino INTEGER;
  v_local       INTEGER;
BEGIN
  v_local := COALESCE(NEW.local_estoque_id, 1);

  CASE NEW.tipo_lancamento::text

    WHEN 'transferencia' THEN
      IF NEW.deposito_id IS NULL THEN
        RAISE EXCEPTION 'Deposito obrigatorio para transferencia avulsa';
      END IF;
      v_dep_destino := COALESCE(NEW.deposito_destino_id, v_dep_almox);
      PERFORM alissonerp.fn_criar_par_movimentacao(
        NEW.insumo_id, NEW.peso,
        NEW.deposito_id, NEW.setor_id,
        v_dep_destino, NULL,
        'TA'::alissonerp.enum_marcador_estoque,
        NULL, NEW.obs, v_local
      );

    WHEN 'entrada' THEN
      INSERT INTO alissonerp.movimentacoes_estoque
        (entrada, saida, insumo_id, deposito_id, setor_id, marcador, obs, created_by, local_estoque_id)
      VALUES
        (NEW.peso, 0, NEW.insumo_id,
         COALESCE(NEW.deposito_id, v_dep_almox), NEW.setor_id,
         'EA'::alissonerp.enum_marcador_estoque,
         NEW.obs, NEW.created_by, v_local);

    WHEN 'saida' THEN
      INSERT INTO alissonerp.movimentacoes_estoque
        (entrada, saida, insumo_id, deposito_id, setor_id, marcador, obs, created_by, local_estoque_id)
      VALUES
        (0, NEW.peso, NEW.insumo_id,
         COALESCE(NEW.deposito_id, v_dep_almox), NEW.setor_id,
         'SA'::alissonerp.enum_marcador_estoque,
         NEW.obs, NEW.created_by, v_local);

    WHEN 'sangria' THEN
      INSERT INTO alissonerp.movimentacoes_estoque
        (entrada, saida, insumo_id, deposito_id, setor_id, marcador, obs, created_by, local_estoque_id)
      VALUES
        (NEW.peso, 0, NEW.insumo_id, v_dep_almox, NULL,
         'Sangria'::alissonerp.enum_marcador_estoque,
         NEW.obs, NEW.created_by, v_local);

    ELSE
      RAISE EXCEPTION 'Tipo de lancamento nao reconhecido: %', NEW.tipo_lancamento;
  END CASE;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_processar_lancamento_avulso(); Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON FUNCTION alissonerp.fn_processar_lancamento_avulso() IS 'Flow 1006: Branch T/E/S/Sangria → CE com marcadores TA/EA/SA/Sangria.';


--
-- Name: fn_processar_outros_insumos_dist(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_processar_outros_insumos_dist() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO alissonerp.movimentacoes_estoque
    (saida, entrada, insumo_id, deposito_id, marcador, local_estoque_id)
  VALUES (NEW.peso, 0, NEW.insumo_id, 1, 'SOID', 1);

  UPDATE alissonerp.distribuicoes SET
    total_outros_pesos       = total_outros_pesos       + NEW.peso,
    total_geral_outros_pesos = total_geral_outros_pesos + NEW.peso,
    updated_at               = now()
  WHERE id = NEW.distribuicao_id;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_processar_outros_insumos_dist(); Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON FUNCTION alissonerp.fn_processar_outros_insumos_dist() IS 'Flow 1010: CE SOID + acumula total_outros_pesos/total_geral_outros_pesos.';


--
-- Name: fn_processar_outros_insumos_pcp(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_processar_outros_insumos_pcp() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO alissonerp.movimentacoes_estoque
    (saida, entrada, insumo_id, deposito_id, marcador, ordem_id, obs, local_estoque_id)
  VALUES
    (NEW.peso, 0, NEW.insumo_id, 1, 'SOI', NEW.ordem_id, 'Outros insumos PCP', 1);

  UPDATE alissonerp.pcp
  SET total_geral_outros_pesos = total_geral_outros_pesos + NEW.peso
  WHERE id = NEW.pcp_id;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_processar_outros_insumos_pcp(); Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON FUNCTION alissonerp.fn_processar_outros_insumos_pcp() IS 'Flow 1004: CE marcador SOI + atualiza total_geral_outros_pesos no PCP.';


--
-- Name: fn_processar_saida_ordem(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_processar_saida_ordem() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_pcp          RECORD;
  v_item         RECORD;
  v_pmc          REAL;
  v_quebra       REAL;
  v_pct          REAL;
  v_ordem        RECORD;
  v_ourives_nome TEXT;
  v_saida_val    REAL;
BEGIN
  -- Guard: ignorar inserts sem peso (saidas vazias criadas pelo Flow 03)
  IF NEW.peso IS NULL OR NEW.peso <= 0 THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_pcp
  FROM alissonerp.pcp
  WHERE ordem_id = NEW.ordem_id
    AND etapas NOT IN ('concluido', 'cancelado')
  ORDER BY id DESC LIMIT 1;

  IF v_pcp.id IS NULL THEN
    RAISE EXCEPTION 'Nenhum PCP ativo encontrado para ordem %', NEW.ordem_id;
  END IF;

  SELECT pmc, quebra, percentual INTO v_pmc, v_quebra, v_pct
  FROM alissonerp.fn_calcular_pmc_pcp(
    NEW.peso,
    COALESCE(v_pcp.total_geral_outros_pesos, 0),
    COALESCE(v_pcp.metal_externo, 0),
    COALESCE(v_pcp.total_metal, 0),
    COALESCE(v_pcp.retorno_metal, 0)
  );

  -- Movimenta????es de estoque (itens da ordem)
  FOR v_item IN
    SELECT ioi.insumo_id, ioi.peso, ioi.deposito_id,
           ins.categoria_id, ins.peso_pedra_ct
    FROM alissonerp.itens_ordem_insumos ioi
    JOIN alissonerp.insumos ins ON ins.id = ioi.insumo_id
    WHERE ioi.ordem_id = NEW.ordem_id AND ioi.peso > 0
  LOOP
    IF v_item.categoria_id = 1 THEN
      -- SM: metal em gramas (inalterado)
      PERFORM alissonerp.fn_criar_par_movimentacao(
        v_item.insumo_id, v_item.peso,
        v_item.deposito_id, NULL, NULL, NULL,
        'SM', NEW.ordem_id,
        'Saida ordem ??? saida_id #' || NEW.id::text,
        1
      );
    ELSE
      -- SP: pedras em ct se peso_pedra_ct dispon??vel (1 ct = 0.2 g)
      IF v_item.categoria_id = 2
         AND v_item.peso_pedra_ct IS NOT NULL
         AND v_item.peso_pedra_ct > 0 THEN
        v_saida_val := v_item.peso / 0.2;
      ELSE
        v_saida_val := v_item.peso;  -- backward compat: gramas
      END IF;
      PERFORM alissonerp.fn_criar_par_movimentacao(
        v_item.insumo_id, v_saida_val,
        v_item.deposito_id, NULL, NULL, NULL,
        'SP', NEW.ordem_id,
        'Saida ordem ??? saida_id #' || NEW.id::text,
        1
      );
    END IF;
  END LOOP;

  -- Concluir PCP (inalterado)
  UPDATE alissonerp.pcp SET
    peso_final            = NEW.peso,
    pmc                   = v_pmc,
    quebra                = v_quebra,
    porcentagem_de_quebra = v_pct,
    saida_ordem_id        = NEW.id,
    etapas                = 'concluido',
    data_conclusao        = now(),
    updated_at            = now()
  WHERE id = v_pcp.id;

  -- Concluir ordem (inalterado)
  UPDATE alissonerp.ordens SET
    status         = 'concluido',
    data_conclusao = now(),
    updated_at     = now()
  WHERE id = NEW.ordem_id;

  -- Dados complementares (inalterado)
  SELECT * INTO v_ordem FROM alissonerp.ordens WHERE id = NEW.ordem_id;

  SELECT up.name INTO v_ourives_nome
  FROM public.user_profiles up
  WHERE up.id_user = v_pcp.operador;

  -- Criar auditoria F??BRICA (inalterado)
  IF NOT EXISTS (
    SELECT 1 FROM alissonerp.auditorias
    WHERE ordem_id = NEW.ordem_id
      AND tipo_auditoria = 'fabrica'
      AND situacao != 'reprovado'
  ) THEN
    INSERT INTO alissonerp.auditorias (
      situacao, tipo_auditoria, rota_processo, ordem_id,
      peso_negociado, peso_final, pmc,
      quebra, quebra_percentual,
      total_metal, retorno_metal, metal_externo,
      ourives_nome
    ) VALUES (
      'pendente',
      'fabrica',
      'saida_pcp',
      NEW.ordem_id,
      COALESCE(v_ordem.peso_metal_negociado, 0),
      COALESCE(NEW.peso, 0),
      COALESCE(v_pmc, 0),
      COALESCE(v_quebra, 0),
      COALESCE(v_pct, 0),
      COALESCE(v_pcp.total_metal, 0),
      COALESCE(v_pcp.retorno_metal, 0),
      COALESCE(v_pcp.metal_externo, 0),
      COALESCE(v_ourives_nome, 'Sem operador')
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_processar_saida_ordem(); Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON FUNCTION alissonerp.fn_processar_saida_ordem() IS 'Conclui PCP + cria auditoria fábrica pendente com dados PMC/quebra.';


--
-- Name: fn_processar_transferencia(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_processar_transferencia() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_ordem   RECORD;
  v_item    RECORD;
BEGIN
  IF NEW.setor_id IS NULL OR NEW.deposito_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.setor_id IS NOT NULL AND OLD.deposito_id IS NOT NULL THEN
      RETURN NEW;
    END IF;
  END IF;

  SELECT local_atual, setor_atual INTO v_ordem
  FROM alissonerp.ordens WHERE id = NEW.ordem_id;

  IF v_ordem.local_atual IS NOT NULL THEN
    FOR v_item IN
      SELECT ioi.insumo_id, ioi.peso
      FROM alissonerp.itens_ordem_insumos ioi
      WHERE ioi.ordem_id = NEW.ordem_id AND ioi.peso > 0
    LOOP
      PERFORM alissonerp.fn_criar_par_movimentacao(
        v_item.insumo_id, v_item.peso,
        v_ordem.local_atual, v_ordem.setor_atual,
        NEW.deposito_id, NEW.setor_id,
        'TED', NEW.ordem_id,
        'Transferencia PCP #' || NEW.pcp_id::text,
        1
      );
    END LOOP;
  END IF;

  UPDATE alissonerp.ordens
  SET setor_atual = NEW.setor_id,
      local_atual = NEW.deposito_id,
      updated_at  = now()
  WHERE id = NEW.ordem_id;

  UPDATE alissonerp.pcp
  SET etapas     = 'em_andamento',
      updated_at = now()
  WHERE id = NEW.pcp_id;

  INSERT INTO alissonerp.transferencias_ordem (pcp_id, ordem_id)
  VALUES (NEW.pcp_id, NEW.ordem_id);

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_processar_transferencia(); Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON FUNCTION alissonerp.fn_processar_transferencia() IS 'Flow 1002: CE TED por insumo entre setores + atualiza local_atual/setor_atual da ordem + PCP→em_andamento + cria próxima transferência vazia.';


--
-- Name: fn_produto_imagens_touch(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_produto_imagens_touch() RETURNS trigger
    LANGUAGE plpgsql
