--
-- Name: fn_proteger_campos_pdv(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_proteger_campos_pdv() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_role TEXT;
DECLARE v_app_role TEXT;
BEGIN
  v_role := COALESCE(current_setting('request.jwt.claims', true)::jsonb->>'role', 'authenticated');
  IF v_role = 'service_role' THEN RETURN NEW; END IF;

  -- Permite desenvolvedor via app.role (setado pela API route com set_config)
  v_app_role := current_setting('app.role', true);
  IF v_app_role = 'desenvolvedor' THEN RETURN NEW; END IF;

  IF NEW.numero_ordem IS DISTINCT FROM OLD.numero_ordem THEN RAISE EXCEPTION 'Campo protegido: numero_ordem'; END IF;
  IF NEW.cliente_id IS DISTINCT FROM OLD.cliente_id THEN RAISE EXCEPTION 'Campo protegido: cliente_id'; END IF;
  IF NEW.vendedor_id IS DISTINCT FROM OLD.vendedor_id THEN RAISE EXCEPTION 'Campo protegido: vendedor_id'; END IF;
  IF NEW.pedido_id IS DISTINCT FROM OLD.pedido_id THEN RAISE EXCEPTION 'Campo protegido: pedido_id'; END IF;
  IF NEW.tipo_ordem IS DISTINCT FROM OLD.tipo_ordem THEN RAISE EXCEPTION 'Campo protegido: tipo_ordem'; END IF;
  IF NEW.data_entrega IS DISTINCT FROM OLD.data_entrega THEN RAISE EXCEPTION 'Campo protegido: data_entrega'; END IF;
  IF NEW.peso_metal_negociado IS DISTINCT FROM OLD.peso_metal_negociado THEN RAISE EXCEPTION 'Campo protegido: peso_metal_negociado'; END IF;
  IF NEW.ficha_tecnica_id IS DISTINCT FROM OLD.ficha_tecnica_id THEN RAISE EXCEPTION 'Campo protegido: ficha_tecnica_id'; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_proteger_itens_venda_fechada(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_proteger_itens_venda_fechada() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'alissonerp', 'directus', 'public'
    AS $$
DECLARE v_situacao TEXT;
BEGIN
  IF current_setting('app.sync_ativo', true) = 'true' THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;

  SELECT situacao INTO v_situacao
  FROM alissonerp.vendas_erp
  WHERE id = COALESCE(NEW.venda_id, OLD.venda_id);

  -- Só 'concluido' bloqueia — 'confirmado' não existe mais no fluxo
  IF v_situacao IN ('concluido') THEN
    RAISE EXCEPTION 'Venda fechada (%). Itens não podem ser alterados.', v_situacao
      USING ERRCODE = 'P0001';
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_proteger_master_admin(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_proteger_master_admin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  master_id UUID;
  current_user_id UUID;
BEGIN
  -- So protege a chave MASTER_ADMIN_USER_ID
  IF COALESCE(OLD.chave, NEW.chave) <> 'MASTER_ADMIN_USER_ID' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  master_id := OLD.valor::uuid;
  current_user_id := auth.uid();

  IF current_user_id IS NULL OR current_user_id <> master_id THEN
    RAISE EXCEPTION 'Apenas o master admin pode alterar MASTER_ADMIN_USER_ID. (tentativa de %, master atual = %)',
      COALESCE(current_user_id::text, 'desconhecido'), master_id;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: fn_proteger_venda_fechada(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_proteger_venda_fechada() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'alissonerp', 'directus', 'public'
    AS $$
BEGIN
  IF current_setting('app.sync_ativo', true) = 'true' THEN RETURN NEW; END IF;

  -- Só 'concluido' é protegido (confirmado removido do fluxo)
  IF OLD.situacao NOT IN ('concluido') THEN RETURN NEW; END IF;

  IF NEW.total_produtos IS DISTINCT FROM OLD.total_produtos
     OR NEW.total_desconto IS DISTINCT FROM OLD.total_desconto
     OR NEW.total_venda IS DISTINCT FROM OLD.total_venda
     OR NEW.total_comissao IS DISTINCT FROM OLD.total_comissao
     OR NEW.total_frete IS DISTINCT FROM OLD.total_frete
     OR NEW.cliente_id IS DISTINCT FROM OLD.cliente_id
     OR NEW.vendedor_id IS DISTINCT FROM OLD.vendedor_id
  THEN
    RAISE EXCEPTION 'Venda fechada (%). Campos financeiros protegidos.', OLD.situacao
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_rastreio_baixa_ouro(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_rastreio_baixa_ouro() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO alissonerp.cofre_ouro_rastreios
    (baixa_id, protocolo_id, evento, gramas, destino_nome, observacao)
  VALUES
    (NEW.id, NEW.protocolo_id,
     CASE NEW.destino
       WHEN 'alisson' THEN 'baixa_direta_alisson'
       ELSE 'baixa_iniciada'
     END,
     NEW.gramas, NEW.destino,
     CASE WHEN NEW.protocolo_id IS NOT NULL THEN 'Protocolo #' || NEW.protocolo_id::text END);
  RETURN NEW;
END;
$$;


--
-- Name: fn_rastreio_compra_metal(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_rastreio_compra_metal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Só registra no cofre quando status muda para 'confirmado'
  -- (evita duplicação em re-processamento)
  IF NEW.status = 'confirmado' AND (OLD.status IS NULL OR OLD.status != 'confirmado') THEN
    INSERT INTO alissonerp.cofre_ouro_rastreios
      (evento, gramas, origem_nome, observacao)
    VALUES
      ('entrada_compra_metal', NEW.peso_gramas, 'Compra Metal',
       'Compra #' || NEW.numero ||
       ' — Fornecedor ID ' || COALESCE(NEW.fornecedor_id::text, 'N/A') ||
       ' — MP Payment: ' || COALESCE(NEW.mp_payment_id, 'N/A'));
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_rastreio_concluir_baixa(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_rastreio_concluir_baixa() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF OLD.status != 'concluido' AND NEW.status = 'concluido' THEN
    INSERT INTO alissonerp.cofre_ouro_rastreios
      (baixa_id, evento, gramas, destino_nome, observacao)
    VALUES
      (NEW.id, 'recebido_confirmado', NEW.gramas,
       NEW.destino, 'Recebido por ' || COALESCE(NEW.recebedor_nome, 'sistema'));
  END IF;
  RETURN NEW;
END;
$$;


