--
-- Name: fn_registrar_transicao_venda(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_registrar_transicao_venda() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'alissonerp', 'directus', 'public'
    AS $$
DECLARE
  v_de   VARCHAR(30) := OLD.situacao;
  v_para VARCHAR(30) := NEW.situacao;
  v_ok   BOOLEAN;
BEGIN
  -- Nao faz nada se situacao nao mudou
  IF v_de IS NOT DISTINCT FROM v_para THEN
    RETURN NEW;
  END IF;

  -- Máquina de estados — Novo fluxo:
  -- rascunho → aprovado → enviado/entregue → concluído
  -- confirmado removido, mas aceito p/ vendas que ainda possuem esse status
  IF v_de IS NULL THEN
    v_ok := v_para = ANY(ARRAY['rascunho','aprovado','confirmado','cancelado']);
  ELSIF v_de = 'rascunho' THEN
    v_ok := v_para = ANY(ARRAY['aprovado','cancelado']);
  ELSIF v_de = 'aprovado' THEN
    -- Novo: pode ir para enviado, entregue, concluido ou cancelado
    v_ok := v_para = ANY(ARRAY['enviado','entregue','concluido','cancelado']);
  ELSIF v_de = 'confirmado' THEN
    -- Mantido para vendas existentes — permite migrar para qualquer status do fluxo
    v_ok := v_para = ANY(ARRAY['aprovado','enviado','entregue','concluido','cancelado']);
  ELSIF v_de = 'enviado' THEN
    v_ok := v_para = ANY(ARRAY['entregue','cancelado']);
  ELSIF v_de = 'entregue' THEN
    v_ok := v_para = ANY(ARRAY['concluido']);
  ELSIF v_de IN ('concluido','cancelado') THEN
    v_ok := false;
  ELSE
    -- Estados desconhecidos: permissivo para compatibilidade futura
    v_ok := true;
  END IF;

  IF NOT v_ok THEN
    RAISE EXCEPTION 'Transição inválida: % → %', COALESCE(v_de, 'NULL'), v_para;
  END IF;

  -- Registrar transição na auditoria
  INSERT INTO alissonerp.vendas_transicoes
    (venda_id, de_situacao, para_situacao, usuario_id, payload)
  VALUES (
    NEW.id,
    v_de,
    v_para,
    auth.uid(),
    jsonb_build_object(
      'total_venda', NEW.total_venda,
      'total_pago',  NEW.total_pago,
      'cliente_id',  NEW.cliente_id,
      'updated_at',  NEW.updated_at
    )
  );

  RETURN NEW;
END;
$$;


--
-- Name: fn_repost_future_sle(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_repost_future_sle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_running NUMERIC(16,4);
  r RECORD;
BEGIN
  SELECT qty_after INTO v_running
  FROM alissonerp.stock_ledger_entry
  WHERE item_id = NEW.item_id
    AND item_type = NEW.item_type
    AND warehouse_id = NEW.warehouse_id
    AND is_cancelled = false
  ORDER BY posting_date DESC, posting_time DESC, id DESC
  LIMIT 1;
  IF v_running IS NULL THEN v_running := NEW.actual_qty; END IF;
  FOR r IN (
    SELECT id, actual_qty FROM alissonerp.stock_ledger_entry
    WHERE item_id = NEW.item_id
      AND item_type = NEW.item_type
      AND warehouse_id = NEW.warehouse_id
      AND is_cancelled = false
      AND (posting_date > NEW.posting_date
           OR (posting_date = NEW.posting_date AND posting_time > NEW.posting_time)
           OR (posting_date = NEW.posting_date AND posting_time = NEW.posting_time AND id > NEW.id))
    ORDER BY posting_date, posting_time, id
    FOR UPDATE
  ) LOOP
    v_running := v_running + r.actual_qty;
    UPDATE alissonerp.stock_ledger_entry SET qty_after = v_running WHERE id = r.id;
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: fn_resumo_recebido_mp(date, date); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_resumo_recebido_mp(p_inicio date DEFAULT NULL::date, p_fim date DEFAULT NULL::date) RETURNS TABLE(qtd bigint, total_bruto numeric, total_taxas numeric, total_liquido numeric)
    LANGUAGE sql STABLE
    AS $$
      SELECT
        COUNT(*)                                    AS qtd,
        COALESCE(SUM(p.valor),         0)::numeric  AS total_bruto,
        COALESCE(SUM(p.taxas_mp),      0)::numeric  AS total_taxas,
        COALESCE(SUM(p.valor_liquido), 0)::numeric  AS total_liquido
      FROM alissonerp.pagamentos_venda p
      WHERE p.gateway LIKE 'Mercado Pago%'
        AND p.status = 'confirmado'
        AND p.data_confirmacao IS NOT NULL
        AND (p_inicio IS NULL OR p.data_confirmacao::date >= p_inicio)
        AND (p_fim    IS NULL OR p.data_confirmacao::date <= p_fim);
    $$;


