--
-- Name: fn_venda_cancelar_conta_receber(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_venda_cancelar_conta_receber() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Só executa se situação mudou para cancelado
  IF NEW.situacao != 'cancelado' OR OLD.situacao = 'cancelado' THEN
    RETURN NEW;
  END IF;

  -- Cancelar conta_receber vinculada
  UPDATE alissonerp.contas_receber
  SET situacao = 'cancelado', updated_at = now()
  WHERE venda_erp_id = NEW.id AND situacao = 'pendente';

  RETURN NEW;
END;
$$;


--
-- Name: fn_venda_gerar_conta_receber(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_venda_gerar_conta_receber() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'alissonerp', 'directus', 'public'
    AS $$
DECLARE
  v_cliente_nome TEXT;
  v_existe BOOLEAN;
BEGIN
  -- Só executa se situação mudou para entregue ou concluido
  IF NEW.situacao NOT IN ('entregue', 'concluido') THEN
    RETURN NEW;
  END IF;

  -- Não reprocessar se já estava em um desses estados
  IF OLD.situacao IN ('entregue', 'concluido') THEN
    RETURN NEW;
  END IF;

  -- Guard duplicata — evitar criar duas contas para mesma venda
  SELECT EXISTS(
    SELECT 1 FROM alissonerp.contas_receber WHERE venda_erp_id = NEW.id
  ) INTO v_existe;

  IF v_existe THEN
    RETURN NEW;
  END IF;

  -- Buscar nome do cliente
  SELECT nome INTO v_cliente_nome
  FROM public.contatos WHERE id_contato = NEW.cliente_id;

  -- Criar conta a receber
  INSERT INTO alissonerp.contas_receber (
    descricao, cliente_id, cliente_nome, venda_erp_id, valor,
    data_vencimento, situacao, categoria, created_by
  ) VALUES (
    'Venda ' || COALESCE(NEW.numero_venda, '#' || NEW.id),
    NEW.cliente_id,
    v_cliente_nome,
    NEW.id,
    NEW.total_venda,
    COALESCE(NEW.data_entrega, CURRENT_DATE + interval '30 days'),
    'pendente',
    'venda',
    NEW.created_by
  );

  RETURN NEW;
END;
$$;


--
-- Name: fn_venda_gerar_conta_receber_on_insert(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.fn_venda_gerar_conta_receber_on_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'alissonerp', 'directus', 'public'
    AS $$
DECLARE
  v_cliente_nome TEXT;
  v_existe BOOLEAN;
BEGIN
  -- Só executa se já nasce entregue ou concluido
  IF NEW.situacao NOT IN ('entregue', 'concluido') THEN
    RETURN NEW;
  END IF;

  -- Guard duplicata
  SELECT EXISTS(
    SELECT 1 FROM alissonerp.contas_receber WHERE venda_erp_id = NEW.id
  ) INTO v_existe;

  IF v_existe THEN
    RETURN NEW;
  END IF;

  -- Buscar nome do cliente
  SELECT nome INTO v_cliente_nome
  FROM public.contatos WHERE id_contato = NEW.cliente_id;

  -- Criar conta a receber
  INSERT INTO alissonerp.contas_receber (
    descricao, cliente_id, cliente_nome, venda_erp_id, valor,
    data_vencimento, situacao, categoria, created_by
  ) VALUES (
    'Venda ' || COALESCE(NEW.numero_venda, '#' || NEW.id),
    NEW.cliente_id,
    v_cliente_nome,
    NEW.id,
    NEW.total_venda,
    COALESCE(NEW.data_entrega, CURRENT_DATE + interval '30 days'),
    'pendente',
    'venda',
    NEW.created_by
  );

  RETURN NEW;
END;
$$;


--
-- Name: gerar_proximo_epc(); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.gerar_proximo_epc() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  ano_atual INT := EXTRACT(YEAR FROM now())::INT - 2000;
  serial    BIGINT;
BEGIN
  -- INSERT com ON CONFLICT garante atomicidade mesmo sob alta concorrencia.
  -- Na 1a chamada do ano: insere (ano, 2) e retorna serial=1 (proximo_serial - 1).
  -- Nas seguintes: incrementa proximo_serial e retorna o valor anterior.
  INSERT INTO alissonerp.epc_serial (ano, proximo_serial)
  VALUES (ano_atual, 2)
  ON CONFLICT (ano) DO UPDATE
    SET proximo_serial = alissonerp.epc_serial.proximo_serial + 1,
        atualizado_em  = now()
  RETURNING proximo_serial - 1 INTO serial;

  RETURN 'AJ' || LPAD(ano_atual::TEXT, 2, '0') || LPAD(serial::TEXT, 8, '0');
END;
$$;


--
-- Name: FUNCTION gerar_proximo_epc(); Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON FUNCTION alissonerp.gerar_proximo_epc() IS 'Gera proximo EPC sequencial no formato AJ{AA}{NNNNNNNN} (12 chars ASCII / 96 bits hex). Atomico.';


--
-- Name: get_sle_balance(bigint, text, integer); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.get_sle_balance(p_item_id bigint, p_item_type text DEFAULT 'produto'::text, p_warehouse_id integer DEFAULT NULL::integer) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN (
    SELECT COALESCE(SUM(actual_qty), 0)::NUMERIC(16,4)
    FROM alissonerp.stock_ledger_entry
    WHERE item_id = p_item_id
      AND item_type = p_item_type
      AND (p_warehouse_id IS NULL OR warehouse_id = p_warehouse_id)
      AND is_cancelled = false
  );
END;
$$;


--
-- Name: get_sle_balance_all(bigint, text); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.get_sle_balance_all(p_item_id bigint, p_item_type text DEFAULT 'produto'::text) RETURNS TABLE(warehouse_id integer, warehouse_nome text, saldo_fisico numeric)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    sle.warehouse_id,
    l.nome,
    COALESCE(SUM(sle.actual_qty), 0)::NUMERIC(16,4)
  FROM alissonerp.stock_ledger_entry sle
  JOIN alissonerp.locais_estoque l ON l.id = sle.warehouse_id
  WHERE sle.item_id = p_item_id
    AND sle.item_type = p_item_type
    AND sle.is_cancelled = false
  GROUP BY sle.warehouse_id, l.nome
  ORDER BY l.nome;
END;
$$;


--
-- Name: get_stock_ledger_report(bigint, integer, date, date); Type: FUNCTION; Schema: alissonerp; Owner: -
--

CREATE FUNCTION alissonerp.get_stock_ledger_report(p_item_id bigint DEFAULT NULL::bigint, p_warehouse_id integer DEFAULT NULL::integer, p_from_date date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date) RETURNS TABLE(id bigint, item_id bigint, item_nome text, item_sku text, warehouse_nome text, actual_qty numeric, qty_after numeric, voucher_type text, voucher_id integer, posting_date date, created_by_email text, is_cancelled boolean)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    sle.id,
    sle.item_id,
    COALESCE(p.nome, i.nome)::TEXT AS item_nome,
    COALESCE(p.sku, i.sku)::TEXT AS item_sku,
    l.nome::TEXT AS warehouse_nome,
    sle.actual_qty,
    sle.qty_after,
    sle.voucher_type,
    sle.voucher_id,
    sle.posting_date,
    u.email::TEXT AS created_by_email,
    sle.is_cancelled
  FROM alissonerp.stock_ledger_entry sle
  JOIN alissonerp.locais_estoque l ON l.id = sle.warehouse_id
  LEFT JOIN public.produtos p ON sle.item_type = 'produto' AND p.id_produto = sle.item_id
  LEFT JOIN alissonerp.insumos i ON sle.item_type = 'insumo' AND i.id = sle.item_id
  LEFT JOIN auth.users u ON u.id = sle.created_by
  WHERE (p_item_id IS NULL OR sle.item_id = p_item_id)
    AND (p_warehouse_id IS NULL OR sle.warehouse_id = p_warehouse_id)
    AND (p_from_date IS NULL OR sle.posting_date >= p_from_date)
    AND (p_to_date IS NULL OR sle.posting_date <= p_to_date)
  ORDER BY sle.posting_date, sle.posting_time, sle.id;
END;
$$;


