--
-- Name: config_orcamento; Type: TABLE; Schema: alissonerp; Owner: -
--

CREATE TABLE alissonerp.config_orcamento (
    id integer NOT NULL,
    name character varying(50) DEFAULT 'default'::character varying NOT NULL,
    start_mkp numeric(6,2) DEFAULT 3.5 NOT NULL,
    discount_percent numeric(5,2) DEFAULT 0 NOT NULL,
    gold_price numeric(10,2) DEFAULT 0 NOT NULL,
    camera_override numeric(6,1),
    profile character varying(30) DEFAULT 'Anatomica'::character varying,
    pricing_categories jsonb DEFAULT '[]'::jsonb NOT NULL,
    groove_rules jsonb DEFAULT '[]'::jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    stone_markup numeric(6,2) DEFAULT 2.5 NOT NULL,
    stone_prices jsonb DEFAULT '[{"tipo": "diamante", "preco_usd_ct": 80}, {"tipo": "moissanita", "preco_usd_ct": 15}, {"tipo": "rubi", "preco_usd_ct": 50}, {"tipo": "esmeralda", "preco_usd_ct": 60}, {"tipo": "safira", "preco_usd_ct": 45}]'::jsonb NOT NULL,
    calibracao jsonb DEFAULT '{"largura_min": {"grao": 0.8, "pave": 1.4, "canaleta": 1.0}, "folga_pedras": 0.2, "espessura_min": {"constante": 0.50, "multiplicador": 0.60}}'::jsonb,
    risco_width numeric(5,2) DEFAULT 0.10,
    risco_depth numeric(5,2) DEFAULT 0.20,
    preco_gravacao numeric(10,2) DEFAULT 100.00,
    stone_markups_table jsonb DEFAULT '{}'::jsonb,
    espessura_minima_por_modelo jsonb DEFAULT '{"boleada": 1.0, "concava": 1.0, "simples": 1.0, "anatomica": 1.0, "chanfrada": 1.0, "boleada_double": 1.0, "quadrado_canal": 1.0}'::jsonb,
    nomes_modelos jsonb DEFAULT '{"boleada": "Boleada", "concava": "Concava", "simples": "Reta", "anatomica": "Anatomica", "chanfrada": "Chanfrada", "boleada_double": "Boleada DF", "quadrado_canal": "Bordas Elevadas"}'::jsonb,
    promocao_inicio date,
    promocao_fim date,
    dome_percentage numeric DEFAULT 100,
    snapshot_lock_enabled boolean DEFAULT true NOT NULL,
    teor_ouro_default integer DEFAULT 75,
    acrescimo_metal_premium numeric(5,2) DEFAULT 30,
    ajuste_pedra_pct numeric(5,2) DEFAULT 100,
    labels_ficha_tecnica jsonb DEFAULT '{}'::jsonb,
    CONSTRAINT chk_acrescimo_metal_premium CHECK (((acrescimo_metal_premium >= (0)::numeric) AND (acrescimo_metal_premium <= (100)::numeric))),
    CONSTRAINT chk_ajuste_pedra_pct CHECK (((ajuste_pedra_pct >= (1)::numeric) AND (ajuste_pedra_pct <= (500)::numeric))),
    CONSTRAINT chk_promocao_periodo CHECK ((((promocao_inicio IS NULL) AND (promocao_fim IS NULL)) OR ((promocao_inicio IS NOT NULL) AND (promocao_fim IS NOT NULL) AND (promocao_inicio <= promocao_fim)))),
    CONSTRAINT chk_teor_ouro_default CHECK (((teor_ouro_default >= 67) AND (teor_ouro_default <= 75)))
);


--
-- Name: COLUMN config_orcamento.calibracao; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.config_orcamento.calibracao IS 'Parametros de validacao do orcamento de aliancas. Espessura minima = pedra*multiplicador + constante. Largura minima varia por tipo de cravacao (canaleta/grao/pave). Folga = espaco minimo entre pedras.';


--
-- Name: COLUMN config_orcamento.stone_markups_table; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.config_orcamento.stone_markups_table IS 'Markups por pedra por tamanho. Ex: {"diamante":{"0":3.9,"1":3.7,...}}';


