    epc text NOT NULL,
    produto_id bigint,
    sku text NOT NULL,
    nome text NOT NULL,
    categoria text,
    peso_g numeric(8,3),
    preco_venda numeric(10,2),
    localizacao_atual text DEFAULT 'fabrica'::text NOT NULL,
    status text DEFAULT 'ativo'::text NOT NULL,
    criado_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    venda_id integer,
    item_venda_id integer,
    sold_at timestamp with time zone,
    reservado_em timestamp with time zone,
    CONSTRAINT joias_rfid_status_check CHECK ((status = ANY (ARRAY['ativo'::text, 'pendente_impressao'::text, 'cancelado'::text, 'reservado'::text, 'vendido'::text, 'em_transito'::text, 'troca'::text])))
);


--
-- Name: TABLE joias_rfid; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON TABLE alissonerp.joias_rfid IS '1 linha = 1 joia fisica com EPC unico. Dados do produto desnormalizados no momento do cadastro (snapshot).';


--
-- Name: COLUMN joias_rfid.epc; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.joias_rfid.epc IS 'Electronic Product Code unico (AJ{AA}{NNNNNNNN}) gravado na tag RFID.';


--
-- Name: COLUMN joias_rfid.produto_id; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.joias_rfid.produto_id IS 'FK public.produtos.id_produto (BIGINT). SKU/nome/preco copiados como snapshot.';


--
-- Name: COLUMN joias_rfid.localizacao_atual; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.joias_rfid.localizacao_atual IS 'Local atual da peca (ex: fabrica, vitrine, reposicao). Atualizado por eventos futuros.';


--
-- Name: COLUMN joias_rfid.status; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.joias_rfid.status IS 'ativo = rastreavel em producao | pendente_impressao = aguarda confirmacao Zebra | cancelado = removido';


