-- Name: notas_fiscais; Type: TABLE; Schema: alissonerp; Owner: -
--

CREATE TABLE alissonerp.notas_fiscais (
    id integer NOT NULL,
    modelo smallint NOT NULL,
    serie smallint NOT NULL,
    numero integer NOT NULL,
    chave_44 character varying(44),
    empresa_emitente_id integer NOT NULL,
    tipo_operacao character varying(20) NOT NULL,
    origem_tabela character varying(50) NOT NULL,
    origem_id bigint NOT NULL,
    cliente_contato_id bigint,
    natureza_operacao character varying(60) NOT NULL,
    cfop character varying(4),
    valor_produtos numeric(15,2) DEFAULT 0 NOT NULL,
    valor_desconto numeric(15,2) DEFAULT 0 NOT NULL,
    valor_frete numeric(15,2) DEFAULT 0 NOT NULL,
    valor_total numeric(15,2) DEFAULT 0 NOT NULL,
    status character varying(20) DEFAULT 'rascunho'::character varying NOT NULL,
    focus_ref character varying(80),
    xml_assinado text,
    xml_protocolo text,
    pdf_danfe_url text,
    codigo_sefaz character varying(10),
    mensagem_sefaz text,
    emitida_por_user_id uuid,
    ambiente character varying(15) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT notas_fiscais_ambiente_check CHECK (((ambiente)::text = ANY ((ARRAY['homologacao'::character varying, 'producao'::character varying])::text[]))),
    CONSTRAINT notas_fiscais_modelo_check CHECK ((modelo = ANY (ARRAY[55, 65]))),
    CONSTRAINT notas_fiscais_status_check CHECK (((status)::text = ANY ((ARRAY['rascunho'::character varying, 'processando'::character varying, 'autorizada'::character varying, 'rejeitada'::character varying, 'cancelada'::character varying, 'denegada'::character varying, 'inutilizada'::character varying])::text[]))),
    CONSTRAINT notas_fiscais_tipo_operacao_check CHECK (((tipo_operacao)::text = ANY ((ARRAY['venda'::character varying, 'remessa'::character varying, 'devolucao'::character varying, 'conserto'::character varying, 'retorno'::character varying, 'outro'::character varying])::text[])))
);


