    itens_para_fabricacao character varying(50),
    situacao alissonerp.enum_situacao_ordem DEFAULT 'criado'::alissonerp.enum_situacao_ordem,
    status alissonerp.enum_status_ordem DEFAULT 'aguardando'::alissonerp.enum_status_ordem,
    rota alissonerp.enum_rota_ordem,
    tipo_controle character varying(20) DEFAULT 'individual'::character varying,
    setor_atual integer,
    local_atual integer,
    distribuicao_id integer,
    protocolo_loja boolean DEFAULT false,
    id_ordem_relacionada integer,
    id_asana bigint,
    directus_ordem_id integer,
    motivo_reprovacao integer,
    origem_reprovacao text,
    data_conclusao timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    created_by uuid,
    updated_by uuid,
    numero_pedido text,
