CREATE TABLE alissonerp.pagamentos_venda (
    id integer NOT NULL,
    venda_id integer NOT NULL,
    forma character varying(30) NOT NULL,
    gateway character varying(30),
    valor numeric(12,2) NOT NULL,
    parcelas integer DEFAULT 1 NOT NULL,
    status character varying(20) DEFAULT 'pendente'::character varying NOT NULL,
    gateway_id text,
    gateway_payload jsonb,
    data_confirmacao timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    valor_liquido numeric(12,2),
    taxas_mp numeric(12,2),
    vale_troca_id integer,
    caixa_baixa_id integer,
    fin_gateway_id integer,
    ouro_gramas numeric(10,3),
    ouro_valor_grama numeric(10,2),
    source character varying(20),
    ouro_peso numeric(10,3),
    ouro_foto_path text,
    CONSTRAINT pagamentos_venda_source_check CHECK (((source)::text = ANY ((ARRAY['webhook_mp'::character varying, 'manual_mp'::character varying, 'pdv'::character varying, 'manual'::character varying, 'ouro'::character varying, 'dinheiro'::character varying, 'vale_troca'::character varying, 'a_receber'::character varying])::text[])))
);


