);


--
-- Name: pcp; Type: TABLE; Schema: alissonerp; Owner: -
--

CREATE TABLE alissonerp.pcp (
    id integer NOT NULL,
    etapas alissonerp.enum_etapas_pcp DEFAULT 'novas_ordens'::alissonerp.enum_etapas_pcp,
    ordem_id integer,
    saida_ordem_id integer,
    operador uuid,
    bloqueado boolean DEFAULT false,
    local_atual boolean DEFAULT true,
    total_metal real DEFAULT 0,
    retorno_metal real DEFAULT 0,
    total_pedras_un real DEFAULT 0,
    total_pedras_g real DEFAULT 0,
    total_geral_outros_pesos real DEFAULT 0,
    total_outros_pesos_g real DEFAULT 0,
    pmc real DEFAULT 0,
    quebra real DEFAULT 0,
    porcentagem_de_quebra real DEFAULT 0,
    peso_final real DEFAULT 0,
    peso_unitario real DEFAULT 0,
    quantidade real DEFAULT 0,
    metal_externo real DEFAULT 0,
    data_conclusao timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    created_by uuid,
    updated_by uuid,
    deposito_id integer,
    dist_ouro_real real DEFAULT 0,
    dist_pedras_qtd real DEFAULT 0,
    dist_pedras_g real DEFAULT 0,
    dist_quebra real DEFAULT 0,
    total_pedras_ct numeric(10,4) DEFAULT 0,
    rota_etapa_atual integer DEFAULT 1 NOT NULL,
    operador_atribuido_id integer,
    CONSTRAINT pcp_rota_etapa_atual_check CHECK ((rota_etapa_atual >= 1))
);


--
-- Name: COLUMN pcp.dist_ouro_real; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.pcp.dist_ouro_real IS 'Soma de distribuicao_ordens.peso_ouro_real para todas as saídas desta ordem';


--
-- Name: COLUMN pcp.dist_pedras_qtd; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.pcp.dist_pedras_qtd IS 'Soma de qtd_utilizada de distribuicao_saida_pedras para esta ordem';


--
-- Name: COLUMN pcp.dist_pedras_g; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.pcp.dist_pedras_g IS 'Soma de peso_total de distribuicao_saida_pedras para esta ordem';


--
-- Name: COLUMN pcp.dist_quebra; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.pcp.dist_quebra IS 'Soma de distribuicao_ordens.quebra para todas as saídas desta ordem';


--
-- Name: COLUMN pcp.rota_etapa_atual; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.pcp.rota_etapa_atual IS 'Quando a ordem usa rota de fabricação (produto_rota), indica qual etapa (1-indexed) está sendo executada. Default 1 (primeira). Avança quando a fabricação transfere de setor.';


--
-- Name: COLUMN pcp.operador_atribuido_id; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.pcp.operador_atribuido_id IS 'Operador (depósito) atribuído individualmente a esta OF na rota de fabricação. Override sobre a lista de colaboradores do setor (setor_operadores). NULL = qualquer um da lista do setor pode atender.';


