--
-- Name: produto_personalizacao; Type: TABLE; Schema: alissonerp; Owner: -
--

CREATE TABLE alissonerp.produto_personalizacao (
    id integer NOT NULL,
    produto_id bigint NOT NULL,
    tipo character varying(20) DEFAULT 'nome'::character varying NOT NULL,
    obrigatorio boolean DEFAULT true NOT NULL,
    min_caracteres integer DEFAULT 1 NOT NULL,
    max_caracteres integer NOT NULL,
    caracteres_permitidos character varying(30) DEFAULT 'alfa_acento_espaco'::character varying NOT NULL,
    label character varying(100) DEFAULT 'Nome a gravar'::character varying NOT NULL,
    placeholder character varying(100),
    exemplo character varying(100),
    observacao text,
    ativo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    preco_por_letra numeric(10,2),
    peso_por_letra numeric(8,2),
    ordem integer DEFAULT 0 NOT NULL,
    min_valor numeric,
    max_valor numeric,
    preco_extra numeric,
    peso_extra numeric,
    personalizavel boolean DEFAULT true NOT NULL,
    descricao_personalizacao text,
    campos_gratis integer DEFAULT 1,
    preco_campo_adicional numeric(10,2),
    CONSTRAINT produto_personalizacao_campos_gratis_check CHECK ((campos_gratis >= 0)),
    CONSTRAINT produto_personalizacao_caracteres_permitidos_check CHECK (((caracteres_permitidos)::text = ANY ((ARRAY['alfa'::character varying, 'alfa_acento'::character varying, 'alfa_acento_espaco'::character varying, 'alfanum'::character varying, 'alfanum_acento_espaco'::character varying, 'numero'::character varying, 'qualquer'::character varying])::text[]))),
    CONSTRAINT produto_personalizacao_check CHECK ((max_caracteres >= min_caracteres)),
    CONSTRAINT produto_personalizacao_min_caracteres_check CHECK ((min_caracteres >= 0)),
    CONSTRAINT produto_personalizacao_peso_por_letra_check CHECK (((peso_por_letra IS NULL) OR (peso_por_letra >= (0)::numeric))),
    CONSTRAINT produto_personalizacao_preco_campo_adicional_check CHECK (((preco_campo_adicional IS NULL) OR (preco_campo_adicional >= (0)::numeric))),
    CONSTRAINT produto_personalizacao_preco_por_letra_check CHECK (((preco_por_letra IS NULL) OR (preco_por_letra >= (0)::numeric))),
    CONSTRAINT produto_personalizacao_tipo_check CHECK (((tipo)::text = ANY ((ARRAY['nome'::character varying, 'iniciais'::character varying, 'simbolo'::character varying, 'livre'::character varying, 'texto'::character varying, 'numero'::character varying, 'selecao_unica'::character varying, 'selecao_multipla'::character varying, 'data'::character varying])::text[])))
);


--
-- Name: TABLE produto_personalizacao; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON TABLE alissonerp.produto_personalizacao IS 'Campos personalizáveis configurados por produto (1:N). Tipos: texto/numero/selecao_unica/selecao_multipla.';


--
-- Name: COLUMN produto_personalizacao.tipo; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.produto_personalizacao.tipo IS 'Tipo de dado a personalizar: nome | iniciais | data | numero | simbolo | livre.';


--
-- Name: COLUMN produto_personalizacao.obrigatorio; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.produto_personalizacao.obrigatorio IS 'Se true, venda nao pode ser finalizada sem o campo preenchido.';


--
-- Name: COLUMN produto_personalizacao.caracteres_permitidos; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.produto_personalizacao.caracteres_permitidos IS 'alfa=A-Z | alfa_acento=A-Z+acentos | alfa_acento_espaco=A-Z+acentos+espacos | alfanum=A-Z+0-9 | alfanum_acento_espaco | numero=0-9 | qualquer.';


--
-- Name: COLUMN produto_personalizacao.preco_por_letra; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.produto_personalizacao.preco_por_letra IS 'Se preenchido, preco do item na venda = qtd_letras * preco_por_letra (recalculado server-side em POST /api/vendas). Se NULL, usa preco_tiny do produto.';


--
-- Name: COLUMN produto_personalizacao.peso_por_letra; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.produto_personalizacao.peso_por_letra IS 'Se preenchido, peso_estimado do item na venda = qtd_letras * peso_por_letra (recalculado server-side em POST /api/vendas). Se NULL, usa peso_precificado do produto.';


--
-- Name: COLUMN produto_personalizacao.personalizavel; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.produto_personalizacao.personalizavel IS 'Se true, produto exibe campos de personalizacao no wizard de venda. Herdado da tabela de config.';


--
-- Name: COLUMN produto_personalizacao.descricao_personalizacao; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.produto_personalizacao.descricao_personalizacao IS 'Texto livre descritivo da personalizacao esperada (ex: "Gravar nome do casal e data de casamento"). Aparece como guia para a consultora.';


--
-- Name: COLUMN produto_personalizacao.campos_gratis; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.produto_personalizacao.campos_gratis IS 'Quantidade de campos de personalizacao inclusos no preco do produto. Ex: 3 = 3 nomes gratis.';


--
-- Name: COLUMN produto_personalizacao.preco_campo_adicional; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.produto_personalizacao.preco_campo_adicional IS 'Valor cobrado por campo extra alem de campos_gratis. Ex: 100.00 = R$ 100 por nome adicional. Se NULL, nao permite adicionar campos extras.';


--
-- Name: produto_personalizacao_campos; Type: TABLE; Schema: alissonerp; Owner: -
--

CREATE TABLE alissonerp.produto_personalizacao_campos (
    id integer NOT NULL,
    config_id integer NOT NULL,
    label character varying(100) DEFAULT 'Nome a gravar'::character varying NOT NULL,
    placeholder character varying(100),
    exemplo character varying(100),
    tipo character varying(20) DEFAULT 'nome'::character varying NOT NULL,
    obrigatorio boolean DEFAULT true NOT NULL,
    min_caracteres integer DEFAULT 1 NOT NULL,
