    caracteres_permitidos character varying(30) DEFAULT 'alfa_acento_espaco'::character varying NOT NULL,
    posicao integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT produto_personalizacao_campos_caracteres_permitidos_check CHECK (((caracteres_permitidos)::text = ANY ((ARRAY['alfa'::character varying, 'alfa_acento'::character varying, 'alfa_acento_espaco'::character varying, 'alfanum'::character varying, 'alfanum_acento_espaco'::character varying, 'numero'::character varying, 'qualquer'::character varying])::text[]))),
    CONSTRAINT produto_personalizacao_campos_check CHECK ((max_caracteres >= min_caracteres)),
    CONSTRAINT produto_personalizacao_campos_min_caracteres_check CHECK ((min_caracteres >= 0)),
    CONSTRAINT produto_personalizacao_campos_posicao_check CHECK ((posicao >= 0)),
    CONSTRAINT produto_personalizacao_campos_tipo_check CHECK (((tipo)::text = ANY ((ARRAY['nome'::character varying, 'iniciais'::character varying, 'data'::character varying, 'numero'::character varying, 'simbolo'::character varying, 'livre'::character varying])::text[])))
);


--
