--
-- Name: COLUMN produto_personalizacao_regras.sem_numeros; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.produto_personalizacao_regras.sem_numeros IS 'Se true, remove numeros do valor digitado.';


--
-- Name: COLUMN produto_personalizacao_regras.sem_simbolos; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.produto_personalizacao_regras.sem_simbolos IS 'Se true, remove simbolos/pontuacao do valor digitado.';


--
-- Name: COLUMN produto_personalizacao_regras.sem_acentos; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.produto_personalizacao_regras.sem_acentos IS 'Se true, remove acentos do valor digitado.';


