--
-- Name: produto_reposicao_config; Type: TABLE; Schema: alissonerp; Owner: -
--

CREATE TABLE alissonerp.produto_reposicao_config (
    produto_id bigint NOT NULL,
    estoque_minimo integer DEFAULT 0 NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tempo_fabricacao_dias integer,
    CONSTRAINT produto_reposicao_config_estoque_minimo_check CHECK ((estoque_minimo >= 0)),
    CONSTRAINT produto_reposicao_config_tempo_fabricacao_dias_check CHECK (((tempo_fabricacao_dias IS NULL) OR (tempo_fabricacao_dias >= 0)))
);


--
-- Name: TABLE produto_reposicao_config; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON TABLE alissonerp.produto_reposicao_config IS 'Configuração de reposição automática por produto. Quando saldo+OFs_abertas < estoque_minimo, cria OFs de fabricação de 1 unidade até cobrir.';


--
-- Name: COLUMN produto_reposicao_config.estoque_minimo; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.produto_reposicao_config.estoque_minimo IS 'Saldo mínimo desejado. Reposição se ativa pra (saldo_atual + qtd_em_OFs_abertas) < estoque_minimo.';


--
-- Name: COLUMN produto_reposicao_config.ativo; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.produto_reposicao_config.ativo IS 'Se false, desabilita reposição automática para esse produto (mantém o registro/configuração).';


--
-- Name: COLUMN produto_reposicao_config.tempo_fabricacao_dias; Type: COMMENT; Schema: alissonerp; Owner: -
--

COMMENT ON COLUMN alissonerp.produto_reposicao_config.tempo_fabricacao_dias IS 'Tempo padrão de fabricação da peça em dias. Usado pelo auto-OF (data_entrega = hoje + N) e exibido como prazo informativo no cadastro/drawer do produto.';


