    CONSTRAINT chk_voucher_type_valid CHECK ((voucher_type = ANY (ARRAY['venda'::text, 'ordem_producao'::text, 'transferencia'::text, 'inventario'::text, 'reconciliacao'::text, 'compra'::text, 'devolucao'::text, 'quebra'::text, 'producao_auto'::text, 'ajuste_entrada'::text, 'ajuste_saida'::text, 'sangria'::text, 'manual'::text]))),
