--
-- Name: vw_auditorias_completa; Type: VIEW; Schema: alissonerp; Owner: -
--

CREATE VIEW alissonerp.vw_auditorias_completa AS
 SELECT a.id,
    a.situacao,
        CASE a.situacao
            WHEN 'pendente'::text THEN 'Pendente'::character varying
            WHEN 'em_analise'::text THEN 'Em Análise'::character varying
            WHEN 'aprovado'::text THEN 'Aprovada'::character varying
            WHEN 'reprovado'::text THEN 'Reprovada'::character varying
            WHEN 'pendenciado'::text THEN 'Pendenciada'::character varying
            ELSE a.situacao
        END AS situacao_label,
    a.tipo_auditoria,
        CASE a.tipo_auditoria
            WHEN 'loja'::text THEN 'Auditoria Loja'::character varying
            WHEN 'fabrica'::text THEN 'Auditoria Fábrica'::character varying
            ELSE COALESCE(a.tipo_auditoria, 'Outro'::character varying)
        END AS tipo_auditoria_label,
    a.rota_processo,
    a.ordem_id,
    o.numero_ordem,
    o.numero_pedido,
    (o.tipo_ordem)::text AS tipo_ordem,
    (o.rota)::text AS rota_ordem,
    a.ourives_nome,
    COALESCE(a.peso_negociado, (0)::real) AS peso_negociado,
    COALESCE(a.peso_final, (0)::real) AS peso_final,
    COALESCE(a.pmc, (0)::real) AS pmc,
    COALESCE(a.quebra, (0)::real) AS quebra,
    COALESCE(a.quebra_percentual, (0)::real) AS quebra_percentual,
    COALESCE(a.total_metal, (0)::real) AS total_metal,
    COALESCE(a.retorno_metal, (0)::real) AS retorno_metal,
    COALESCE(a.metal_externo, (0)::real) AS metal_externo,
    a.ficha_tecnica_obs,
    a.dados_ordem,
        CASE
            WHEN ((COALESCE(a.peso_negociado, (0)::real) > (0)::double precision) AND (COALESCE(a.peso_final, (0)::real) > (0)::double precision)) THEN round(((((a.peso_final - a.peso_negociado) / a.peso_negociado) * (100)::double precision))::numeric, 1)
            ELSE (0)::numeric
        END AS diff_peso_pct,
    a.responsavel_id,
    up.name AS responsavel_nome,
    a.parecer,
    a.motivo_reprovacao,
    a.tipo_retrabalho,
    a.ordem_retrabalho_id,
    oret.numero_ordem AS ordem_retrabalho_numero,
    c.nome AS cliente_nome,
    v.nome AS vendedor_nome,
    a.created_at,
    a.data_conclusao,
    round((EXTRACT(epoch FROM (COALESCE(a.data_conclusao, now()) - a.created_at)) / 86400.0), 1) AS dias_analise,
    o.data_entrega,
    COALESCE(o.peso_metal_externo, (0)::real) AS peso_metal_externo,
    o.detalhes_ordem
   FROM (((((alissonerp.auditorias a
     LEFT JOIN alissonerp.ordens o ON ((o.id = a.ordem_id)))
     LEFT JOIN public.user_profiles up ON ((up.id_user = a.responsavel_id)))
     LEFT JOIN alissonerp.ordens oret ON ((oret.id = a.ordem_retrabalho_id)))
     LEFT JOIN public.contatos c ON ((c.id_contato = o.cliente_id)))
     LEFT JOIN public.vendedores v ON ((v.id_vendedor = o.vendedor_id)));


--
-- Name: vw_cofre_ouro; Type: VIEW; Schema: alissonerp; Owner: -
--

CREATE VIEW alissonerp.vw_cofre_ouro AS
 SELECT (count(*))::integer AS total_transacoes,
    COALESCE(sum(COALESCE(pv.ouro_peso, pv.ouro_gramas)), (0)::numeric) AS total_gramas,
    COALESCE(sum(pv.valor), (0)::numeric) AS total_valor_brl,
    COALESCE(avg(pv.ouro_valor_grama) FILTER (WHERE (pv.ouro_valor_grama > (0)::numeric)), (0)::numeric) AS preco_medio_grama,
    (count(*) FILTER (WHERE (pv.created_at >= (now() - '30 days'::interval))))::integer AS transacoes_30d,
    COALESCE(sum(COALESCE(pv.ouro_peso, pv.ouro_gramas)) FILTER (WHERE (pv.created_at >= (now() - '30 days'::interval))), (0)::numeric) AS gramas_30d,
    COALESCE(sum(pv.valor) FILTER (WHERE (pv.created_at >= (now() - '30 days'::interval))), (0)::numeric) AS valor_brl_30d
   FROM alissonerp.pagamentos_venda pv
  WHERE (((pv.forma)::text = 'Ouro'::text) AND ((pv.status)::text = 'confirmado'::text));


--
-- Name: vw_cofre_ouro_disponivel; Type: VIEW; Schema: alissonerp; Owner: -
--

CREATE VIEW alissonerp.vw_cofre_ouro_disponivel AS
 WITH vendas_ouro AS (
         SELECT (count(*))::integer AS transacoes,
            COALESCE(sum(COALESCE(pv.ouro_peso, pv.ouro_gramas)), (0)::numeric) AS gramas,
            COALESCE(sum(pv.valor), (0)::numeric) AS valor_brl,
            COALESCE(avg(pv.ouro_valor_grama) FILTER (WHERE (pv.ouro_valor_grama > (0)::numeric)), (0)::numeric) AS preco_medio_grama
           FROM alissonerp.pagamentos_venda pv
          WHERE (((pv.forma)::text = 'Ouro'::text) AND ((pv.status)::text = 'confirmado'::text))
        ), compras_metal AS (
         SELECT (count(*))::integer AS transacoes,
            COALESCE(sum(cm.peso_gramas), (0)::numeric) AS gramas,
            COALESCE(sum(cm.valor_total), (0)::numeric) AS valor_brl
           FROM alissonerp.compras_metal cm
          WHERE (((cm.status)::text = 'confirmado'::text) AND (cm.cofre_registrado = true))
        ), recebimentos_metal AS (
         SELECT (count(*))::integer AS transacoes,
            COALESCE(sum(rm.peso_gramas), (0)::numeric) AS gramas,
            COALESCE(sum(rm.valor_total), (0)::numeric) AS valor_brl
           FROM alissonerp.recebimentos_metal rm
          WHERE (((rm.status)::text = 'ativo'::text) AND (rm.cofre_registrado = true))
        ), conversoes AS (
         SELECT (count(*))::integer AS transacoes,
            COALESCE(sum(ce.peso_total), (0)::numeric) AS gramas,
            (0)::numeric AS valor_brl
           FROM alissonerp.conversoes_estoque ce
          WHERE (((ce.status_conversao)::text = 'concluido'::text) AND (ce.cofre_registrado = true))
        ), total_entradas AS (
         SELECT (((v.transacoes + c.transacoes) + r.transacoes) + cv.transacoes) AS total_transacoes,
            (((v.gramas + c.gramas) + r.gramas) + cv.gramas) AS total_gramas,
            (((v.valor_brl + c.valor_brl) + r.valor_brl) + cv.valor_brl) AS total_valor_brl,
            v.preco_medio_grama
           FROM (((vendas_ouro v
             CROSS JOIN compras_metal c)
             CROSS JOIN recebimentos_metal r)
             CROSS JOIN conversoes cv)
        ), baixas AS (
         SELECT COALESCE(sum(cb.gramas), (0)::numeric) AS baixado_gramas
           FROM alissonerp.cofre_ouro_baixas cb
          WHERE ((cb.status)::text = ANY ((ARRAY['pendente'::character varying, 'em_trafego'::character varying, 'concluido'::character varying])::text[]))
        )
 SELECT e.total_transacoes,
    e.total_gramas,
    (e.total_gramas - b.baixado_gramas) AS disponivel_gramas,
    e.total_valor_brl,
    e.preco_medio_grama
   FROM (total_entradas e
     CROSS JOIN baixas b);


