    pedidos_parcelas_detalhado.meio_pagamento_pedido,
    pedidos_parcelas_detalhado.data_vencimento_parcela,
    pedidos_parcelas_detalhado.valor_parcela,
    pedidos_parcelas_detalhado.forma_pagamento_parcela,
