            WHEN '9'::text THEN 'Jade (risco lateral, escovado)'::character varying
            WHEN '10'::text THEN 'Quartzo Rosa (bordas chanfradas)'::character varying
            WHEN '11'::text THEN 'Ametista (risco no meio)'::character varying
