            WHEN '13'::text THEN 'Baguet'::character varying
            WHEN '14'::text THEN '3 em 1'::character varying
            WHEN '15'::text THEN 'Outros'::character varying
            ELSE ft.tipo_elo
        END AS tipo_elo_label,
    ft.outro_tipo_elo,
    ft.tipo_fecho,
