--
-- Name: vw_vendas_completa; Type: VIEW; Schema: alissonerp; Owner: -
--

CREATE VIEW alissonerp.vw_vendas_completa AS
 SELECT v.id,
    v.numero_pedido,
    v.data_venda,
    v.total_venda,
    v.total_produtos,
    v.total_itens_qnt,
    v.status,
    v.entregue,
    v.dados_pagamento,
    v.observacoes,
    c.nome AS cliente_nome,
    c.cpf_cnpj AS cliente_cpf,
    ve.nome AS vendedor_nome,
    ve.id_vendedor AS vendedor_id
   FROM ((public.vendas v
     LEFT JOIN public.contatos c ON ((c.id_contato = v.cliente_id)))
     LEFT JOIN public.vendedores ve ON ((ve.id_vendedor = v.vendedor_id)));


--
-- Name: vw_vendas_erp_completa; Type: VIEW; Schema: alissonerp; Owner: -
--

CREATE VIEW alissonerp.vw_vendas_erp_completa AS
 SELECT v.id,
    v.numero_venda,
    v.cliente_id,
    c.nome AS cliente_nome,
    c.cpf_cnpj AS cliente_cpf_cnpj,
    c.email AS cliente_email,
    c.telefone AS cliente_telefone,
    v.vendedor_id,
    vend.nome AS vendedor_nome,
    v.data_venda,
    v.data_entrega,
    v.total_produtos,
    v.total_desconto,
    v.total_frete,
    v.total_venda,
    v.total_comissao,
    v.situacao,
    v.forma_envio,
    v.forma_frete,
    v.observacoes,
    v.observacoes_internas,
    v.video_obs_interna,
    v.tiny_pedido_id,
    v.tiny_sync_status,
    v.tiny_sync_at,
    v.tiny_sync_erro,
    v.bloqueado,
    v.is_legacy,
    v.created_by,
    v.created_at,
    v.updated_at,
    COALESCE(( SELECT count(*) AS count
           FROM alissonerp.itens_venda_erp i
          WHERE (i.venda_id = v.id)), (0)::bigint) AS qtd_itens,
    COALESCE(( SELECT sum(p.valor) AS sum
           FROM alissonerp.pagamentos_venda p
          WHERE ((p.venda_id = v.id) AND ((p.status)::text = 'confirmado'::text))), (0)::numeric) AS total_pago
   FROM ((alissonerp.vendas_erp v
     LEFT JOIN public.contatos c ON ((c.id_contato = v.cliente_id)))
     LEFT JOIN public.vendedores vend ON ((vend.id_vendedor = v.vendedor_id)));


