-- Name: contasareceberdetalhada; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.contasareceberdetalhada AS
 SELECT cr.id_api_conta,
    cr.situacao,
    cr.data,
    cr.data_vencimento,
    cr.data_competencia,
    cr.data_liquidacao,
    cr.valor,
    cr.saldo,
    cr.juros,
    cr.multa,
    cr.valor_pago,
    cr.forma_recebimento,
    c.descricao AS nomecategoria,
    c.grupo AS nomegrupo,
    p.data_pedido,
    p.id_api_pedido AS numero_pedido,
    (cr.pedido_id_api IS NOT NULL) AS tem_relacao_com_pedido
   FROM ((public.contas_a_receber cr
     JOIN public.categorias_receitas_despesas c ON ((cr.categoria_id_api = c.id_api_categoria)))
     LEFT JOIN public.pedidos p ON ((cr.pedido_id_api = p.id_api_pedido)));


