--
-- Name: crm_user_perfil; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.crm_user_perfil WITH (security_invoker='true') AS
 SELECT au.id AS user_id,
    au.email,
    eu.nome,
    eu.role,
    eu.vendedor_id,
    v.nome AS vendedor_nome,
    v.foto AS vendedor_foto,
    v.email AS vendedor_email
   FROM ((auth.users au
     LEFT JOIN alissonerp.usuarios eu ON ((eu.id = au.id)))
     LEFT JOIN public.vendedores v ON ((v.id_vendedor = eu.vendedor_id)));


