    status text DEFAULT 'confirmado'::text NOT NULL,
    diferenca_valor numeric(12,2) DEFAULT 0 NOT NULL,
    diferenca_dias integer DEFAULT 0 NOT NULL,
    confirmado_em timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT fin_conciliacoes_status_check CHECK ((status = ANY (ARRAY['confirmado'::text, 'divergente'::text])))
);


