    importado_em timestamp with time zone DEFAULT now() NOT NULL,
    arquivo_id uuid,
    conteudo_ofx text,
    n8n_execution_id character varying(255),
    CONSTRAINT fin_extratos_bancarios_status_check CHECK ((status = ANY (ARRAY['processando'::text, 'concluido'::text, 'erro'::text])))
);


--
-- Name: TABLE fin_extratos_bancarios; Type: COMMENT; Schema: public; Owner: -
