COMMENT ON TABLE public.fin_extratos_bancarios IS 'Extratos OFX/CSV importados pela Esmeralda';


--
-- Name: fin_lancamentos_bancarios; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.fin_lancamentos_bancarios (
    id bigint NOT NULL,
    extrato_id bigint NOT NULL,
    data_lancamento date NOT NULL,
    descricao text,
    valor numeric(12,2) NOT NULL,
    tipo text NOT NULL,
    fitid text NOT NULL,
    CONSTRAINT fin_lancamentos_bancarios_tipo_check CHECK ((tipo = ANY (ARRAY['debito'::text, 'credito'::text])))
);


--
-- Name: TABLE fin_lancamentos_bancarios; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.fin_lancamentos_bancarios IS 'Lançamentos individuais do extrato bancário';


--
-- Name: COLUMN fin_lancamentos_bancarios.fitid; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.fin_lancamentos_bancarios.fitid IS 'ID único OFX — garante idempotência no reimport';


--
-- Name: fin_divergencias_pendentes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.fin_divergencias_pendentes AS
 SELECT c.id AS conciliacao_id,
    cp.id AS conta_pagar_id,
    cp.historico AS descricao,
    cp.fornecedor_id_api,
    cp.valor AS valor_tiny,
    abs(lb.valor) AS valor_banco,
    c.diferenca_valor,
    c.diferenca_dias,
    cp.data_vencimento,
    lb.data_lancamento,
    lb.descricao AS historico_banco,
    eb.banco,
    c.created_at AS detectado_em
   FROM (((public.fin_conciliacoes c
     JOIN public.contas_a_pagar cp ON ((cp.id = c.conta_pagar_id)))
     JOIN public.fin_lancamentos_bancarios lb ON ((lb.id = c.lancamento_id)))
     JOIN public.fin_extratos_bancarios eb ON ((eb.id = lb.extrato_id)))
  WHERE (c.status = 'divergente'::text)
  ORDER BY cp.data_vencimento;


--
-- Name: VIEW fin_divergencias_pendentes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.fin_divergencias_pendentes IS 'Esmeralda vê apenas divergências — matches perfeitos são invisíveis';


