-- Name: pedidos_dashboard; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.pedidos_dashboard AS
 SELECT p.id_api_pedido,
    p.data_pedido,
    p.numero_pedido,
    p.valor_total_pedido,
    p.valor_frete,
    v.id_vendedor,
    (pp_vale.pedido_id_api IS NOT NULL) AS possui_vale_troca,
    COALESCE(sum(pp_vale.valor), (0)::double precision) AS valor_vale_troca
   FROM ((public.pedidos p
     LEFT JOIN public.vendedores v ON ((p.vendedor_id_api = v.id_api_vendedor)))
     LEFT JOIN public.parcelas_pedidos pp_vale ON (((p.id_api_pedido = pp_vale.pedido_id_api) AND (pp_vale.forma_pagamento = 'Vale-troca'::text))))
  GROUP BY p.id_api_pedido, p.numero_pedido, p.data_pedido, p.valor_total_pedido, p.valor_frete, v.id_vendedor, pp_vale.pedido_id_api;


