--
-- Name: produtos_views; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.produtos_views AS
 SELECT p.id_api_produto,
    p.sku,
    p.nome,
    p.tipo_metal,
    p.peso_precificado,
    p.fornecedor_etl,
    p.tipo_de_pedra,
    p.data_atualizacao,
    pai.id_api_produto AS produto_pai_id,
        CASE
            WHEN (POSITION(('-'::text) IN (p.sku)) > 0) THEN 'Variação'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.produtos v
              WHERE ((v.sku)::text ~~ ((p.sku)::text || '-%'::text)))) THEN 'Pai'::text
            ELSE 'Simples'::text
        END AS tipo_produto
   FROM (public.produtos p
     LEFT JOIN public.produtos pai ON (((pai.sku)::text =
        CASE
            WHEN (POSITION(('-'::text) IN (p.sku)) > 0) THEN "substring"((p.sku)::text, 1, (POSITION(('-'::text) IN (p.sku)) - 1))
            ELSE NULL::text
        END)));


