--

CREATE POLICY config_select_by_manager_flag ON public.config_orcamento_aliancas FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.vendedores v
  WHERE ((TRIM(BOTH FROM lower(v.email)) = TRIM(BOTH FROM lower(auth.email()))) AND (v.gerente_orcamento = true)))));


